window.EXAM_DATA = [{"year": "112", "subject": "建築法規", "officialSubject": "營建法規與實務", "durationMinutes": 120, "questions": [{"number": 1, "prompt": "下列何者非屬於建築法所稱之建造行為？", "options": ["新建", "增建", "改建", "拆除"], "answer": "D"}, {"number": 2, "prompt": "建築師參與建築物統包工程，有關建築法規之設計簽證責任屬於下列何者？", "options": ["共同投標之代表廠商", "營造廠", "建築師", "依投資比例分擔"], "answer": "C"}, {"number": 3, "prompt": "依建築法規定，下列何者屬起造人申請建造執照時，應備具之書件？", "options": ["建築物權利證明文件", "土地權利證明文件", "原建築物使用執照", "工程合約"], "answer": "B"}, {"number": 4, "prompt": "依建築物室內裝修管理辦法規定，除住宅外建築物 11 層以上樓層，室內裝修之樓地板面積在多少平 方公尺以下，且在室內裝修範圍內以 1 小時以上防火時效之防火牆、防火門窗區劃分隔，其未變更防 火避難設施、消防安全設備、防火區劃及主要構造者，得請建築師或室內裝修業申報施工，經主管建 築機關核給期限後，准予進行施工？", "options": ["100 平方公尺", "200 平方公尺", "300 平方公尺", "400 平方公尺"], "answer": "A"}, {"number": 5, "prompt": "依建築基地法定空地分割辦法規定，建築基地之法定空地併同建築物之分割，分割後應符合之規定， 下列何者正確？", "options": ["每一建築基地之法定空地與建築物所占地面應相連接，連接部分寬度不得小於 3.5 公尺", "每一建築基地之建築物高度應合於規定", "每一建築基地均應連接建築線並得以單獨申請建築", "每一建築基地之建築物無須具獨立之出入口"], "answer": "C"}, {"number": 6, "prompt": "依建築師法之規定，下列何者非中華民國全國建築師公會的會員？", "options": ["臺北市建築師公會", "桃園市建築師公會", "彰化縣建築師公會", "臺灣省建築師公會"], "answer": "D"}, {"number": 7, "prompt": "依建築技術規則規定，建築物用途類組非供 H-2 組使用，高度至少達幾公尺以上者，應辦理防火避難 綜合檢討評定，或檢具經中央主管建築機關認可之建築物防火避難性能設計計畫書及評定書？", "options": ["70", "80", "90", "100"], "answer": "C"}, {"number": 8, "prompt": "下列何者非屬建築技術規則規定之無窗戶居室？", "options": ["可直接開向戶外或可通達戶外之有效防火避難構造開口，其高度為 1.1 公尺，寬度為 70 公分", "樓地板面積為 100 平方公尺，有效採光面積為 4 平方公尺", "可直接開向戶外或可通達戶外之有效防火避難構造開口，圓型直徑為 1.2 公尺者", "樓地板面積超過 50 平方公尺之居室，其天花板或天花板下方 80 公分範圍以內之有效通風面積未達 樓地板面積 2%者"], "answer": "C"}, {"number": 9, "prompt": "依建築技術規則有關高層建築物之規定，高層建築物之總樓地板面積與留設空地之比不得大於一定 值，如基地屬工業區其值為何？", "options": ["15", "20", "25", "30"], "answer": "A"}, {"number": 10, "prompt": "依建築技術規則工廠類建築物專章之規定，下列敘述何者正確？", "options": ["工廠類建築物每一樓層之衛生設備應分散設置，以方便使用", "作業廠房各項附屬空間合計樓地板面積不得超過作業廠房面積之 1/5", "作業廠房之樓層高度扣除直上層樓地板厚度及樑深後之淨高度不得小於 2.7 公尺", "作業廠房樓地板面積 3000 平方公尺以上者，應設一處裝卸位 代號：1801 頁次：8－2"], "answer": "C"}, {"number": 11, "prompt": "下列何者為建築技術規則所稱之「防火設備」？", "options": ["防火門窗", "防焰窗簾", "消防栓", "火災警報器"], "answer": "A"}, {"number": 12, "prompt": "依建築技術規則規定，老人住宅之臥室，其樓地板面積應為 9 平方公尺以上，居住人數最多不得超過 多少人？", "options": ["1", "2", "3", "4"], "answer": "D"}, {"number": 13, "prompt": "下列何者不是建築技術規則所稱的特定建築物？", "options": ["電影院", "學校", "汽車加油站", "總樓地板面積 1000 平方公尺的集合住宅"], "answer": "D"}, {"number": 14, "prompt": "依建築技術規則規定，防火門分為常時關閉式及常時開放式兩種，下列有關防火門之敘述，何者錯誤？", "options": ["常時關閉式之防火門，單一門扇面積不得超過 3 平方公尺", "應於門扇或門樘標示常時關閉式防火門", "門扇寬度應在 75 公分以上，高度應在 180 公分以上", "開關五金不屬防火門組件可依設計需求任意替換"], "answer": "D"}, {"number": 15, "prompt": "室內裝修專業技術人員有下列何種情事，當地主管建築機關應查明屬實後，報請內政部廢止登記許可 並註銷登記證？", "options": ["受委託設計之圖樣、說明書、竣工查驗合格簽章之檢查表或其他書件經抽查結果與相關法令規定不符", "未依審核合格圖說施工", "規避、妨礙或拒絕主管機關業務督導", "專業技術人員登記證供所受聘室內裝修業以外使用"], "answer": "D"}, {"number": 16, "prompt": "室內裝修施工中變更設計，遇有下列何種情形得依「建築物室內裝修管理辦法」第 31 條規定修改竣 工圖說，一次報驗？", "options": ["增設室內樓梯", "變更防火區劃", "調整避難層出入口及走廊之寬度", "提升天花板耐燃等級"], "answer": "B"}, {"number": 17, "prompt": "有關建築物室內裝修從業者之規定，下列敘述何者錯誤？", "options": ["依法登記開業之綜合營造業得從事室內裝修施工業務", "開業建築師欲從事室內裝修設計業務，必須先向內政部申請核發專業設計技術人員登記證，俾利納管", "聘有專業設計技術人員之室內裝修業，得從事室內裝修設計業務", "室內裝修業從事室內裝修施工業務者，應置有專業施工技術人員一人以上"], "answer": "A"}, {"number": 18, "prompt": "依據建築技術規則建築設計施工編規定，新建建築物於計算容積總樓地板面積時，下列何種項目無論 面積大小，其所占面積均不可以扣除？", "options": ["一般昇降機的機道", "緊急昇降機的機道", "安全梯的梯間", "特別安全梯的排煙室"], "answer": "D"}, {"number": 19, "prompt": "依建築技術規則，有關緩衝區之設置規定，下列敘述何者錯誤？", "options": ["緩衝區位於地下建築物或地下運輸系統與建築物地下層之連接處", "緩衝區具有專用直通樓梯供緊急避難", "緩衝區與連接之地下運輸系統及建築物之地下層間應以具有 1 小時以上防火時效之牆壁、防火門窗 等防火設備及該層防火構造之樓地板區劃分隔", "緩衝區及其專用直通樓梯位於建築基地內時，應計入建築面積及容積總樓地板面積"], "answer": "B"}, {"number": 20, "prompt": "依建築技術規則規定，高層建築物地下各層最大樓地板面積之計算公式 Ao≦（1＋Q）A/2，下列敘述 何者正確？", "options": ["公式中之 Q，為該案件實際設計之建蔽率", "公式中之 Q，為該基地依都市計畫及建築有關法令規定之法定最大建蔽率", "公式中之 A，為該案件實際設計之建築面積", "公式中之 A，為該基地依都市計畫及建築有關法令規定之法定最大建築面積"], "answer": "B"}, {"number": 21, "prompt": "依據建築技術規則建築設計施工編規定，有關建築面積之計算，部分構造得在符合特定條件下不計入 建築面積。上述所稱部分構造，不包括下列何項？", "options": ["電業單位規定之配電設備及其防護設施", "基地內兩幢建築物間之高架人行道", "地下層突出基地地面未超過 1.2 公尺", "遮陽板有 1/2 以上為透空，且其深度在 2.0 公尺以下者 代號：1801 頁次：8－3"], "answer": "C"}, {"number": 22, "prompt": "依建築技術規則規定，有關公共建築物之無障礙設施設計，下列敘述何者正確？", "options": ["公共建築物之建築基地面積未達 150 平方公尺者，可免設置無障礙設施", "公共建築物每棟每層之樓地板面積均未達 100 平方公尺者，可免設置無障礙設施", "公共建築物因建築基地地形、垂直增建、構造或使用用途特殊，設置無障礙設施確有困難，經當地 主管建築機關核准者，得不適用建築技術規則無障礙建築物專章一部或全部之規定", "公共建築物無論符合任何條件，均應設置無障礙設施"], "answer": "C"}, {"number": 23, "prompt": "依建築技術規則，有關建築物之防火及防火避難設施相關規定，下列敘述何者正確？", "options": ["耐燃等級是用來描述建築物主要結構構件、防火設備及防火區劃構造遭受火災時可耐火之時間", "防焰性能是用來描述建築構造當其一面受火時，能在一定時間內，其非加熱面溫度不超過規定值之 能力", "遮煙性能是在常溫及中溫標準試驗條件下，建築物出入口裝設之一般門或區劃出入口裝設之防火設 備，當其構造二側形成火災情境下之壓差時，具有漏煙通氣量不超過規定值之能力", "防火時效是用來描述建築物之內部裝修材料因應火熱引起燃燒、熔化、破裂變形及產生有害氣體時 不超過規定值之能力"], "answer": "D"}, {"number": 24, "prompt": "為協助老舊公寓增設昇降機，以解決高齡者上下樓層的障礙問題。依現行建築技術規則修訂放寬的法 規內容，不包含下列何者？", "options": ["建築面積及各層樓地板面積之限制", "鄰棟間隔及前後院落之限制", "避難層開向屋外之出入口寬度及開口距離之限制", "屋頂突出物高度之限制"], "answer": "B"}, {"number": 25, "prompt": "依山坡地建築管理辦法第 4 條，起造人申請雜項執照，下列何者非為必要檢附的文件？", "options": ["申請書、土地權利證明文件、工程圖樣及說明書", "建築物平面圖與立面圖", "水土保持計畫核定證明文件或免擬具水土保持計畫之證明文件", "依環境影響評估法相關規定應實施環境影響評估者，檢附審查通過之文件"], "answer": "B"}, {"number": 26, "prompt": "依違章建築處理辦法，直轄市、縣（市）主管建築機關，應於接到違章建築查報人員報告之日起最多 幾日內實施勘查，認定必須拆除者，應即拆除之？", "options": ["3", "5", "10", "15"], "answer": "B"}, {"number": 27, "prompt": "依建築師法規定，建築師未經領有開業證書、已撤銷或廢止開業證書、未加入建築師公會或受停止執 行業務處分而擅自執業者，除勒令停業外，並處新臺幣多少元之罰鍰；其不遵從而繼續執業者，得按 次連續處罰？", "options": ["6000 元以上 20000 元以下", "10000 元以上 30000 元以下", "20000 元以上 60000 元以下", "30000 元以上 100000 元以下"], "answer": "B"}, {"number": 28, "prompt": "依建築師法，領有建築師證書，具有至少幾年以上建築工程經驗者，得申請發給開業證書？", "options": ["1", "2", "3", "4"], "answer": "B"}, {"number": 29, "prompt": "依建築師法規定，領有開業證書之建築師，應於開業證書有效期間屆滿日之 3 個月前，檢具原領開業 證書及內政部認可機構、團體出具之研習證明文件，向所在直轄市、縣（市）主管機關申請換發開業 證書。請問，建築師開業證書有效期間為幾年？", "options": ["5", "6", "7", "8"], "answer": "B"}, {"number": 30, "prompt": "依建築技術規則規定，防空避難設備使用之樓地板面積至少達到多少平方公尺以上，僅能兼做停車空 間使用？", "options": ["150", "200", "300", "500"], "answer": "B"}, {"number": 31, "prompt": "依原有合法建築物公共安全改善辦法規定，供商場使用者，直通樓梯總寬度以其直上層以上各層中任 何一層之最大樓地板面積每 100 平方公尺至少寬多少公分為計算值，並以避難層作分界，分別核計其 直通樓梯總寬度？", "options": ["50", "60", "70", "80 代號：1801 頁次：8－4"], "answer": "B"}, {"number": 32, "prompt": "依建築師法規定，建築師經主管機關之指定，應襄助辦理之事項，不包含下列何者？", "options": ["公共安全", "公共交通", "社會福利", "預防災害"], "answer": "B"}, {"number": 33, "prompt": "依建築法規定，建築法施行前，供公眾使用之建築物而未領有使用執照者，其所有權人應如何處理？", "options": ["應申請核發使用執照", "應申請建造執照拆除重建", "應申請核發建造執照", "應申請核發雜項執照"], "answer": "C"}, {"number": 34, "prompt": "依建築法規定，起造人自接獲通知領取建造執照之日起，至多逾幾個月未領取者，主管建築機關得將 該執照予以廢止？", "options": ["1", "3", "6", "9"], "answer": "D"}, {"number": 35, "prompt": "依建築法規定，山坡地建築之審查許可、施工管理及使用管理等事項之辦法，由下列何者定之？", "options": ["中央山坡地主管機關", "當地山坡地主管機關", "中央主管建築機關", "當地主管建築機關"], "answer": "C"}, {"number": 36, "prompt": "依建築法規定，百貨公司設置一定規模以上之招牌廣告，應向下列何者申請審查許可？", "options": ["中央商業主管機關", "直轄市、縣（市）商業主管機關", "中央主管建築機關", "直轄市、縣（市）主管建築機關"], "answer": "D"}, {"number": 37, "prompt": "依建築法規定，申請建造執照案件，起造人應於接獲第一次通知改正之日起至多幾個月內，依照通知 改正事項改正完竣送請復審？", "options": ["1", "3", "6", "9"], "answer": "B"}, {"number": 38, "prompt": "依都市計畫法規定，有關都市計畫公共設施之敘述，下列何者錯誤？", "options": ["公共設施保留地在未取得前，得申請為臨時建築使用", "私有公共設施保留地得申請與公有非公用土地辦理交換，不受土地法、國有財產法及各級政府財產 管理法令相關規定之限制；劃設逾 25 年未經政府取得者，得優先辦理交換", "公園、體育場所、綠地、廣場及兒童遊樂場，應依計畫人口密度及自然環境，作有系統之布置，除 具有特殊情形外，其占用土地總面積不得少於全部計畫面積 10%", "屠宰場、垃圾處理場、殯儀館、火葬場、公墓、污水處理廠、煤氣廠等應在不妨礙都市發展及鄰近 居民之安全、安寧與衛生之原則下，應按居民分布情形適當配置之"], "answer": "B"}, {"number": 39, "prompt": "依建築法規定，下列敘述何者正確？", "options": ["監造人認為不合規定或承造人擅自施工，至必須修改、拆除、重建或予補強，經主管建築機關認定 者，由承造人及監造人負賠償責任", "監造人認為不合規定或承造人擅自施工，至必須修改、拆除、重建或予補強，經主管建築機關認定 者，由承造人負賠償責任", "承造人未按核准圖說施工，而監造人認為合格經直轄市、縣（市）（局）主管建築機關勘驗不合規 定，必須修改、拆除、重建或補強者，由承造人負賠償責任，監造人負連帶責任，承造人之專任工 程人員免負連帶責任", "承造人未按核准圖說施工，而監造人認為合格經直轄市、縣（市）（局）主管建築機關勘驗不合規 定，必須修改、拆除、重建或補強者，由承造人負賠償責任，承造人之專任工程人員負連帶責任， 監造人免負連帶責任"], "answer": "C"}, {"number": 40, "prompt": "依違章建築處理辦法，既存違章建築影響公共安全者，當地主管建築機關應訂定拆除計畫限期拆除； 不影響公共安全者，由當地主管建築機關分類分期予以列管拆除。有關影響公共安全之範圍（不考慮 經當地主管建築機關認有必要情形），下列敘述何者錯誤？", "options": ["供營業使用之整幢違章建築。營業使用之對象由當地主管建築機關於查報及拆除計畫中定之", "合法建築物垂直增建一層違章建築", "合法建築物水平增建違章建築，占用防火間隔", "合法建築物水平增建違章建築，占用騎樓"], "answer": "B"}, {"number": 41, "prompt": "依建築法規定，下列敘述何者正確？", "options": ["起造人自領得建造執照之日起，應於 12 個月內開工", "起造人因故不能於規定期限內開工時，應敘明原因，申請展期 1 次，期限為 6 個月", "承造人因故未能於建築期限內完工時，得申請展期 1 年，並以 1 次為限", "建築期限基準，於建築技術規則中定之 代號：1801 頁次：8－5"], "answer": "B"}, {"number": 42, "prompt": "依建築技術規則之規定，山坡地設計時計算平均坡度之正方格坵塊，其每邊長至多不大於多少公尺？", "options": ["20", "25", "30", "35"], "answer": "D"}, {"number": 43, "prompt": "依都市計畫公共設施保留地臨時建築使用辦法規定，在公共設施道路及綠地保留地上，申請臨時建築 者，限於計畫寬度在 15 公尺寬以上，並應於其兩側至少各保留多少公尺寬之通路？", "options": ["2", "4", "6", "8"], "answer": "C"}, {"number": 44, "prompt": "依都市計畫法規定，新訂、擴大或變更都市計畫時，得先行劃定計畫地區範圍，經由該管都市計畫委 員會通過後，得禁止該地區內一切建築物之新建、增建、改建，並禁止變更地形或大規模採取土石。 下列有關禁建之敘述，何者正確？", "options": ["禁建範圍及期限，由各級都委會核定。禁止期限，視計畫地區範圍之大小及舉辦事業之性質定之。 但最長不得超過 1 年 6 個月", "禁建範圍及期限，由各級都委會核定。禁止期限，視計畫地區範圍之大小及舉辦事業之性質定之。 但最長不得超過 2 年", "禁建範圍及期限，由行政院核定。禁止期限，視計畫地區範圍之大小及舉辦事業之性質定之。但最 長不得超過 1 年 6 個月", "禁建範圍及期限，由行政院核定。禁止期限，視計畫地區範圍之大小及舉辦事業之性質定之。但最 長不得超過 2 年"], "answer": "D"}, {"number": 45, "prompt": "依都市更新建築容積獎勵辦法規定，取得候選智慧建築證書，給予一定之獎勵容積。下列敘述何者正 確？", "options": ["鑽石級：基準容積 8%、黃金級：基準容積 6%", "銀級：基準容積 4%、銅級：基準容積 2%", "鑽石級：基準容積 10%、黃金級：基準容積 8%", "銀級：基準容積 8%、銅級：基準容積 6%"], "answer": "C"}, {"number": 46, "prompt": "依都市更新條例規定，有關政府主導都市更新之敘述何者錯誤？", "options": ["各級主管機關得成立都市更新推動小組，督導、推動都市更新政策及協調政府主導都市更新業務", "直轄市、縣（市）主管機關得自行實施或經公開評選委託都市更新事業機構為實施者實施", "直轄市、縣（市）主管機關得同意其他機關（構）自行實施或經公開評選委託都市更新事業機構為 實施者實施", "公開評選實施者，應於公告徵求都市更新事業機構申請後，於擬實施都市更新事業之地區，舉行說 明會"], "answer": "B"}, {"number": 47, "prompt": "依都市更新條例規定，各級主管機關得視實際需要，劃定或變更策略性更新地區，並訂定或變更都市 更新計畫之情形，不包含下列何者？", "options": ["位於鐵路場站、捷運場站或航空站一定範圍內", "位於都會區水岸、港灣周邊適合高度再開發地區者", "為適應國防建設工程需要", "其他配合重大發展建設需要辦理都市更新者"], "answer": "B"}, {"number": 48, "prompt": "依都市更新條例規定，各級主管機關劃定或變更策略性更新地區，屬政府主導都市更新方式辦理者， 且更新單元面積達 1 萬平方公尺以上，其獎勵後之建築容積敘述，何者正確？", "options": ["不得超過各該建築基地 1.5 倍之基準容積，或各該建築基地 0.5 倍之基準容積再加其原建築容積", "不得超過各該建築基地 2 倍之基準容積，或各該建築基地 0.5 倍之基準容積再加其原建築容積", "不得超過各該建築基地 1.5 倍之基準容積，或各該建築基地 1 倍之基準容積再加其原建築容積", "不得超過各該建築基地 2 倍之基準容積，或各該建築基地 1 倍之基準容積再加其原建築容積"], "answer": "D"}, {"number": 49, "prompt": "都市更新事業計畫核定後，直轄市、縣（市）主管機關得視實際需要隨時或定期檢查實施者對該事業 計畫之執行情形。前述所定之定期檢查，至少多久應實施一次？", "options": ["每 3 個月", "每 6 個月", "每 1 年", "每 2 年 代號：1801 頁次：8－6"], "answer": "A"}, {"number": 50, "prompt": "依都市更新建築容積獎勵辦法規定，下列敘述何者正確？", "options": ["實施容積管制前已興建完成之合法建築物，其原建築容積高於基準容積者，得依原建築容積建築， 或依原建築基地基準容積 15%給予獎勵容積", "都市更新事業計畫範圍內之建築物，經建築主管機關依建築法規、災害防救法規通知限期拆除、逕 予強制拆除，或評估有危險之虞應限期補強或拆除者，給予基準容積 15%獎勵容積", "都市更新事業計畫範圍內之建築物，經結構安全性能評估結果未達最低等級者，給予基準容積 10% 獎勵容積", "都市更新事業計畫範圍內之古蹟、歷史建築、紀念建築及聚落建築群，辦理整體性保存、修復、再 利用及管理維護者，除不計入容積外，並得依該建築物實際面積之 1.5 倍，給予獎勵容積"], "answer": "A"}, {"number": 51, "prompt": "依都市更新建築容積獎勵辦法規定，處理占有他人土地之舊違章建築戶，依都市更新事業計畫報核前 之實測面積給予獎勵容積，且每戶不得超過最近一次行政院主計總處人口及住宅普查報告各該直轄 市、縣（市）平均每戶住宅樓地板面積，其獎勵額度以基準容積多少為上限？", "options": ["20%", "30%", "40%", "50%"], "answer": "D"}, {"number": 52, "prompt": "依國土計畫法規定，城鄉發展地區規劃基本原則下列何者錯誤？", "options": ["以確保糧食安全為原則", "以成長管理為原則", "創造寧適和諧之生活環境及有效率之生產環境", "確保完整之配套公共設施"], "answer": "C"}, {"number": 53, "prompt": "依國土計畫法規定，若有下列情事各級國土計畫得適時檢討變更之。惟何者為錯誤？", "options": ["因戰爭、地震、水災、風災、火災或其他重大事變遭受損壞", "為加強資源保育或避免重大災害之發生", "政府興辦國防，重大之公共設施或公用事業計畫", "為適應經濟發展需要"], "answer": "D"}, {"number": 54, "prompt": "依據國土計畫法規定，於符合國土功能分區及其分類之使用原則下，從事一定規模以上或性質特殊之 土地使用，下列敘述何者正確？", "options": ["一定規模以上或性質特殊之土地使用，其認定標準，由所在地直轄市、縣（市）主管機關認定", "申請使用許可範圍屬國土保育地區者，由直轄市、縣（市）主管機關受理及審議", "申請使用許可範圍跨二個直轄市、縣（市）行政區以上者，由中央主管機關審議", "填海造地案件者，由所在地直轄市、縣（市）主管機關審議"], "answer": "D"}, {"number": 55, "prompt": "依國土計畫法規定，直轄市、縣（市）主管機關有諸多應辦理事項，下列何者正確？", "options": ["全國國土計畫之擬定、公告、變更及實施", "國土功能分區劃設順序、劃設原則之規劃", "使用許可制度及全國性土地使用管制之擬定", "農業發展地區或城鄉發展地區之使用許可、許可變更及廢止之核定"], "answer": "B"}, {"number": 56, "prompt": "依國家公園法規定，在史蹟保存區、特別景觀區或生態保護區內，下列何者得經國家公園管理處許可 辦理，其餘均應予禁止？", "options": ["水面水道之填塞改道或擴展", "土地開墾或變更使用", "垂釣魚類或放牧牲畜", "纜車等機械化運輸設備之興建"], "answer": "D"}, {"number": 57, "prompt": "依區域計畫法施行細則規定，各級主管機關擬定區域計畫時，其計畫年期以不超過多少年為原則？", "options": ["30 年", "25 年", "20 年", "10 年"], "answer": "A"}, {"number": 58, "prompt": "依區域計畫法規定，申請開發許可案件之審議期限，下列何者正確？", "options": ["直轄市、縣（市）政府應於受理後 120 日內，報請各區域計畫擬定機關辦理許可審議", "區域計畫擬定機關應於 120 日內將審議結果通知申請人", "但有特殊情形者，予延長一次，其延長期限應不得超過 120 日之期限", "直轄市、縣（市）政府不依規定期限，將案件報請區域計畫擬定機關審議者，其上級主管機關得令 其一定期限內為之；逾期仍不為之者，上級主管機關得依申請，逕為辦理許可審議 代號：1801 頁次：8－7"], "answer": "D"}, {"number": 59, "prompt": "依非都市土地使用管制規則規定，依原奬勵投資條例等相關規定開發之工業區或其他政府機關設置開 發之園區，其擴大投資或產業升級轉型之興辦計畫，得依擴大新增投資金額取得增加法定容積後，其 為提升能源使用效率及設置再生能源發電設備，得再予增加法定容積。其規定下列何者正確？", "options": ["設置能源管理系統：百分之二", "設置太陽光電發電設備於廠房屋頂，且水平投影面積占屋頂可設置區域範圍百分之五十以上：百分 之十", "增加容積之審核，在中央由內政部為之；在直轄市、縣（市）由直轄市、縣（市）政府為之", "設置整合型太陽光電設備，得增加容積率百分之五"], "answer": "D"}, {"number": 60, "prompt": "依公寓大廈管理條例規定，屬公寓大廈之一部分，具有使用上之獨立性，且為區分所有之標的者，係 指下列何者？", "options": ["約定共用部分", "約定專用部分", "共用部分", "專有部分"], "answer": "C"}, {"number": 61, "prompt": "直轄市、縣（市）政府得組設公寓大廈爭議事件調處委員會，但申請調處案件如有下列何種情形者， 應不予調處？", "options": ["區分所有權人或住戶積欠管理費事件", "有關管理委員選任事項之爭議事件", "管理委員會未執行區分所有權人會議決議事項", "已訴請法院審理中之案件"], "answer": "B"}, {"number": 62, "prompt": "某公寓大廈屋頂平台擬設置高度 7 公尺之樹立廣告，其申請審查許可之規定，下列敘述何者錯誤？", "options": ["應備具申請書及設計圖說，並委由開業建築師申請雜項執照", "廣告招牌燈之裝設，應依建築技術規則建築設備編相關規定辦理", "免經頂層區分所有權人之同意", "若公寓大廈區分所有權人會議決議或規約規定禁止設置廣告物並經向直轄市、縣（市）主管機關完 成報備有案者，應不予核准"], "answer": "C"}, {"number": 63, "prompt": "下列何者並非「公寓大廈管理條例」規定管理委員會之職務？", "options": ["管理服務人之委任、僱傭及監督", "管理委員之選任及主任委員之推舉", "收益、公共基金及其他經費之收支、保管及運用", "會計報告、結算報告及其他管理事項之提出及公告"], "answer": "A"}, {"number": 64, "prompt": "依公寓大廈管理條例之規定，非屬因急迫情事召開臨時會之區分所有權人會議，應由召集人至少於開 會前幾日以書面載明開會內容，通知各區分所有權人？", "options": ["3 日", "7 日", "10 日", "15 日"], "answer": "D"}, {"number": 65, "prompt": "依公寓大廈管理條例規定，下列何者非屬新建建築物起造人應盡之職務或義務？", "options": ["預售屋買賣定型化契約，非經提送主管機關核備，不得辦理銷售", "應按建築物之工程造價一定比例提撥公共基金", "擔任區分所有權人會議之召集人，召開首次區分所有權人會議", "在公寓大廈未成立管理委員會或推選管理負責人前，起造人為管理負責人"], "answer": "B"}, {"number": 66, "prompt": "依營造業法規定，專業營造業登記之專業工程項目，不包括下列何者？", "options": ["環境保護工程", "庭園、景觀工程", "防水工程", "輕隔間工程"], "answer": "C"}, {"number": 67, "prompt": "依營造業法規定，營造業承攬工程，應依照工程圖樣及說明書製作下列何種文件，並負責施工？", "options": ["地基調查報告", "工地現場施工製造圖及施工計畫書", "規劃報告", "施工可行性研究"], "answer": "A"}, {"number": 68, "prompt": "依營造業法規定，工程主管或主辦機關辦理下列何種事項時，未強制規定營造業之專任工程人員及工 地主任應在現場說明？", "options": ["查驗", "驗收", "調解", "勘驗"], "answer": "C"}, {"number": 69, "prompt": "依營造業法規定，評鑑為第一級之營造業，並經主管機關或經中央主管機關認可之相關機關（構）辦 理複評合格之優良營造業，承攬政府工程時，申領工程預付款，可增加百分之多少？", "options": ["10", "15", "20", "25 代號：1801 頁次：8－8"], "answer": "C"}, {"number": 70, "prompt": "機關委託廠商辦理技術服務，非屬特殊情形或需要高度技術之服務案件，其服務費用採建造費用百分 比法計費者，下列敘述何者正確？", "options": ["同幢建築物用途分屬市場與宿舍者，依各用途樓地板面積所占比率較大者之服務費率統一計算", "建築物之室內裝修工程按室內裝修相關規定計費，不得比照同類之建築物計費", "服務費用占建造費用之百分比，應按金額級距分段計算", "建築師依規定需申請公有建築物候選智慧建築證書，包含於設計監造服務費用內，不另給付"], "answer": "C"}, {"number": 71, "prompt": "依政府採購法規定，機關辦理巨額工程採購，應依採購之特性及實際需要，成立下列何種編組，以協 助審查採購需求與經費、採購策略及招標文件等事項？", "options": ["評選委員會", "稽核小組", "採購工作及審查小組", "查核小組"], "answer": "D"}, {"number": 72, "prompt": "依政府採購法規定，機關辦理工程採購之付款及審核程序，除契約另有約定外，下列敘述何者錯誤？", "options": ["定期估驗或分階段付款者，機關應於廠商提出估驗或階段完成之證明文件後，15 日內完成審核 程序", "機關完成審核程序，接到廠商提出之請款單據後，應於 15 日內付款", "審核程序之日數，係指日曆天，包含例假日及國定假日", "機關辦理審核程序，如發現廠商有文件不符、不足或有疑義，應一次通知澄清或補正，不得分次 辦理"], "answer": "B"}, {"number": 73, "prompt": "依政府採購法相關規定，監造單位及其所派駐現場人員工作重點，不包括下列何者？", "options": ["設備製造商資格之審查", "訂定檢驗停留點，辦理抽查施工作業及抽驗材料設備，並於抽查（驗）紀錄表簽認", "履約進度及履約估驗計價之審核", "督察品管人員及現場施工人員，落實執行品質計畫"], "answer": "C"}, {"number": 74, "prompt": "有關室外通路防護設施之規定，下列何者錯誤？", "options": ["室外通路與鄰近地面高差未達 20 公分者，無設置邊緣防護之必要", "室外通路與鄰近地面高差超過 20 公分者，未鄰牆壁側應設置高度 3 公分之邊緣防護", "室外通路與鄰近地面高差超過 75 公分者，未鄰牆壁側應設置高度 110 公分以上之邊緣防護", "室外通路位於地面層 10 層以上者，防護設施不得小於 120 公分"], "answer": "D"}, {"number": 75, "prompt": "百貨公司之無障礙設施樓梯，梯級的規定，下列何者錯誤？", "options": ["級高應為 16 公分以下", "級深應為 26 公分以上", "梯級突沿之彎曲半徑不得大於 3 公分", "梯級踏面邊緣應作防滑處理，其顏色應與踏面有明顯不同，且應順平"], "answer": "B"}, {"number": 76, "prompt": "無障礙輪椅觀眾席位，席位地面有高差且無適當阻隔者，其防護設施高度規定，下列何者正確？", "options": ["120 公分", "110 公分", "90 公分", "75 公分"], "answer": "B"}, {"number": 77, "prompt": "有關無障礙客房內求助鈴設計，應至少設置 2 處，有關其設置高度，下列何者正確？", "options": ["其中一處求助鈴按鍵中心點距地板高 150 公分", "其中一處求助鈴按鍵中心點距地板高 100 公分", "其中一處求助鈴按鍵中心點距地板高 80 公分", "其中一處求助鈴按鍵中心點距地板高 70 公分"], "answer": "A"}, {"number": 78, "prompt": "依建築物無障礙設施設計規範之無障礙廁所盥洗室之馬桶及扶手規定，下列敘述何者錯誤？", "options": ["馬桶側面牆壁裝置扶手時，應設置 L 型扶手", "水平扶手上緣與馬桶座墊距離為 50 公分", "馬桶至少有一側為可固定之掀起式扶手", "可動扶手外緣與馬桶中心線之距離為 35 公分"], "answer": "D"}, {"number": 79, "prompt": "依建築物無障礙設施設計規範之無障礙停車空間，下列敘述何者正確？", "options": ["單一停車位之汽車停車位長度不得小於 600 公分、寬度不得小於 350 公分", "單一停車位之汽車停車位寬度，包括寬 135 公分之下車區", "相鄰停車位得共用下車區，長度不得小於 600 公分、寬度不得小於 500 公分", "相鄰停車位得共用下車區寬度，包括寬 135 公分之下車區"], "answer": "B"}, {"number": 80, "prompt": "依農業用地興建農舍辦法規定，下列何者非屬申請興建農舍應備具之工程圖樣？", "options": ["農舍平面圖", "農舍立面圖", "農舍剖面圖", "農舍透視圖"], "answer": "A"}], "questionCount": 80, "answerCount": 80}, {"year": "112", "subject": "建築結構", "officialSubject": "建築結構", "durationMinutes": 120, "questions": [{"number": 1, "prompt": "三維空間薄殼結構，係由厚度遠小於他向尺度之一個或多個曲型薄版或摺版所組成。若為混 凝土薄殼結構，下列何者不是其三維承載行為特徵的取決要件？", "options": ["幾何形狀", "受支撐狀況", "作用載重性質", "屬於張力型抗結構"], "answer": "D"}, {"number": 2, "prompt": "下圖的門形構架，梁為剛體（EI=∞），若忽略構件的軸向變形時，當柱的 EI 值不變，但柱高 由 h 增為 2 h 時，則頂層在相同外力下，其側向位移將會增加為原先的多少倍？", "options": ["2 倍", "4 倍", "6 倍", "8 倍"], "answer": "D"}, {"number": 3, "prompt": "下列敘述何者正確？①在同一場地震事件下，各地區震度相同，地震規模相異 ②某次地震 A、B 兩測站加速度分別為 200 gal 與 420 gal，速度分別為 150 cm/sec 與 60 cm/sec，則 A 測 站震度較高 ③建築物耐震設計規範之最大考量地震，其 50 年超越機率約為 5% ④新增活 動斷層之認定係依據經濟部中央地質調查所之公告", "options": ["①④", "③④", "①③", "②④"], "answer": "D"}, {"number": 4, "prompt": "有關材料性質，下列敘述何者正確？", "options": ["若材料加載與變形關係保持線性，其行為必於彈性階段", "應變硬化現象，為指材料因環境溫度改變而在相同受力下應變降低", "進行結構韌性設計，不得採用脆性材料如混凝土", "材料具高韌性比（ductility ratio），即其極限強度遠高於降伏強度"], "answer": "A"}, {"number": 5, "prompt": "關於材料波松比 ν（Poisson's ratio），下列何者錯誤？", "options": ["與材料彈性係數 E、剪力模數 G 相關", "常見範圍為 1≤ν≤3", "圓形桿件軸向拉伸時，會造成斷面直徑變小", "為一無因次之量"], "answer": "B"}, {"number": 6, "prompt": "為抵抗拱結構支承處之外推力，下列設計策略何者不適當？", "options": ["以拉力桿件連接兩端支承", "支承處設計厚重基礎", "減小「拱高／跨度」之比值", "鄰旁增設扶壁"], "answer": "C"}, {"number": 7, "prompt": "關於高層建築物的設計與建築物在地震中的反應，下列敘述何者正確？", "options": ["若材料與構法相同，則高層建築物的自振頻率高於低矮建築物的自振頻率", "建築物在強震中受損後，其自振週期會拉長", "超高層建築物之結構設計應以抗震設計作為最主要考量", "超高層建築物若於頂樓附近的樓板加裝質量塊，即可改善其耐震性能。臺灣著名的地標「臺 北 101」於其高樓層處設置的金色大圓球，便是依此原理而設計"], "answer": "B"}, {"number": 8, "prompt": "一結構如圖所示，上部為一個短柱，底部為兩個面積較小的長柱支撐，中間塗黑部分為剛體， 當頂端受到一外力 P 作用時，最頂部的位移為多少？", "options": ["PL/AE", "4 PL/5 AE", "3 PL/2 AE", "3 PL/5 AE"], "answer": "B"}, {"number": 9, "prompt": "一個微小的矩型六面體受到純剪力作用，下列敘述何者正確？", "options": ["受剪力變形後角度的改變量為剪應變", "剪力彈性模數為 E/(1+2v) ，v 為波松比", "鋼材的剪力降伏應力約為拉力降伏應力的 80%", "剪力彈性模數與彈性模數 E 的單位不同"], "answer": "A"}, {"number": 10, "prompt": "下列知名建築中何者最接近形抗結構？", "options": ["巴黎鐵塔", "北京水立方", "橫濱大棧橋國際客船中心", "高雄 85 大樓"], "answer": "C"}, {"number": 11, "prompt": "圖示管狀結構（Tubular Structure）的外管受側力作用時，若管面為完全剛性，則傾覆彎矩造 成的底部應力會如圖示虛線的線性分布，但實際管狀結構會因剪力遲滯，而造成柱受力的不 同，下列有關柱受力的敘述何者正確？", "options": ["壓力管面之角柱應力較邊柱高，側向管面角柱應力高於線性比例", "壓力管面之角柱應力較邊柱低，側向管面角柱應力高於線性比例", "壓力管面之角柱應力較邊柱高，側向管面角柱應力低於線性比例", "壓力管面之角柱應力較邊柱低，側向管面角柱應力低於線性比例 P 0.6 L2 AE AE AE L 代號：80120 頁次：8－4"], "answer": "A"}, {"number": 12, "prompt": "如下圖所示，一構件斜面之中心點受一水平力 P=1000 N 作用，此斜面與水平方向之夾角為 θ=45°，若該構件垂直面之面積 A0=100 cm2，則沿斜面之平均剪應力 τave 為多少？", "options": ["5 N/cm2", "10 N/cm2", "15 N/cm2", "20 N/cm2"], "answer": "C"}, {"number": 13, "prompt": "下列有關「固定拱」、「雙鉸拱」和「三鉸拱」的敘述，何者錯誤？", "options": ["固定拱及雙鉸拱為靜不定結構，三鉸拱則為靜定結構", "固定拱會因基礎不均勻沉陷導致撓曲應力", "雙鉸拱之支承點處會承受外推力，三鉸拱則否", "固定拱及雙鉸拱會因溫度變化導致撓曲應力"], "answer": "B"}, {"number": 14, "prompt": "下列有關纜索結構系統的敘述，何者正確？", "options": ["纜索能抵抗張力及壓力", "纜索會隨著外力作用而改變形態", "纜索承受本身自重時，會形成拋物線的形狀", "纜索承受均布載重時，會形成懸鏈線的形狀"], "answer": "B"}, {"number": 15, "prompt": "醫院欲加裝緊急發電機，業主要求該發電機需於強震後正常運作，下列敘述何者正確？①設 置於屋頂層可降低該發電機地震力需求 ②設置於較低樓層可降低發電機承受之樓板加速度 ③發電機可依建築物耐震設計規範以靜力設計錨定強度 ④在功能相同的條件下，應採較重 之發電機避免受震傾覆", "options": ["①④", "②③", "①③", "②④"], "answer": "B"}, {"number": 16, "prompt": "下列何種設計策略會增長建物基本振動週期？", "options": ["增大柱斷面", "增設隔震器", "增設剪力牆", "減低柱高"], "answer": "C"}, {"number": 17, "prompt": "關於鋼結構柱的挫屈，下列何者正確？", "options": ["挫屈強度正比於柱有效長度（kL）", "支承條件由鉸接改為固定端，其有效長度（kL）變長", "迴轉半徑（r）只與桿件斷面幾何條件有關", "迴轉半徑（r）越小，挫屈強度 Pcr 越大"], "answer": "B"}, {"number": 18, "prompt": "圖中所示為三根鋼結構構件的斷面形狀與尺寸。如果這三根構件的長度一致並使用相同的材 料，下列敘述何者正確？ (i) (ii) (iii)", "options": ["若作為柱子使用，則斷面(i)可承受最高的軸向負載", "若作為簡支梁使用，則斷面(ii)可承受最高的彎矩負載", "若作為懸臂梁使用，則斷面(iii)可承受最高的剪力負載", "若作為邊梁使用（該梁承受扭矩），則斷面(i)具有最高的抗扭能力 P=1000 N A0=100 cm2 P=1000 N θ=45°"], "answer": "D"}, {"number": 19, "prompt": "下圖中之圖(i)為一棟兩跨的單層鋼筋混凝土造建築物的結構示意圖。該建築物在遭受恐怖攻 擊後，結構局部受損。受損後的建築物如圖(ii)所示，除了中央柱被炸斷外，在數個梁柱接頭 處也因混凝土嚴重剝落而形成鉸接點。關於受損前後的建築結構，下列敘述何者正確？ (i) (ii)", "options": ["受損前的建築物[圖(i)]是靜定結構", "受損後的建築物[圖(ii)]是靜定結構", "受損前的建築物[圖(i)]是一次靜不定結構", "受損後的建築物[圖(ii)]是內部不穩定結構"], "answer": "C"}, {"number": 20, "prompt": "關於承重牆結構系統特性，下列敘述何者正確？", "options": ["承重牆系統因不受梁、柱模矩的限制，因此在建築物完工後，可輕易地改變牆壁位置，增 加室內空間使用彈性", "為提升視覺舒適度、氣派感受、或空間趣味性，設計上常見樓板大面積挑空、大廳挑高或 夾層之設計。在此類設計中，落柱會破壞其空間感，因此建築結構可考慮採用承重牆系統", "採用承重牆系統時，上下相鄰樓層的牆體應儘量垂直對齊", "做為大班制教室（超過百人）使用的建築物，因特殊用途教室與普通教室所需要的空間大 小相差甚多，若採承重牆系統可令空間規劃更具彈性"], "answer": "C"}, {"number": 21, "prompt": "關於隔震系統，下列敘述何者錯誤？", "options": ["天然橡膠隔震墊阻尼小於鉛心橡膠隔震墊", "摩擦單擺隔震系統的隔震週期由滑動面曲率決定", "適用於超高層結構", "隔震結構並非適用於各類型地盤"], "answer": "C"}, {"number": 22, "prompt": "對一個寬度為 b 深度為 h 的矩形斷面梁的斷面模數（S）及塑性斷面模數（Z），下列敘述何 者錯誤？", "options": ["S=bh 2/6", "S 乘上降伏應力為降伏彎矩", "Z=bh 2/3", "Z 乘上降伏應力為全斷面達塑性時之彎矩"], "answer": "C"}, {"number": 23, "prompt": "如下圖所示之四種桁架結構，各桿件之軸向剛度（AE）值皆相等。若溫度改變時，何者最有 可能產生桿件內部應力？", "options": ["", "", "", "代號：80120 頁次：8－6"], "answer": "D"}, {"number": 24, "prompt": "桁架於 E 點受力 P，DF 軸力為何？", "options": ["0", "P/2 3 （拉）", "P/2（拉）", "-P/ 3"], "answer": "B"}, {"number": 25, "prompt": "下圖所示結構中，支承 A 與 B 的反力大小為何？", "options": ["RA=20 kN, RB=75 kN", "RA=25 kN, RB=100 kN", "RA=15 kN, RB=80 kN", "RA=50 kN, RB=100 kN"], "answer": "A"}, {"number": 26, "prompt": "下圖中之圖(i)所示為一單跨抗彎矩構架（moment-resisting frame）的示意圖。該構架由兩根鋼 筋混凝土柱(1)與(2)支撐灰色區域所示的剛體梁；這兩根柱子的側向力與變形關係曲線繪於圖 (ii)之中[註：柱子的邊界條件與圖(i)相同]。有關此構架行為的敘述，何者正確？ (i) (ii)", "options": ["若構架的層間變位是 Δ1，則此時施加於構架上的外力為 F=V 1+V 2", "若施加於構架上的外力 F=V 3，則此時構架產生的層間變位為 Δ=Δ2+Δ3", "若先把構架推到層間變位為 Δ3 處然後完全卸載，之後重新加載直到層間變位為 Δ1，此時 柱(1)內部的剪力為 V1", "若先把構架推到層間變位為 Δ1 處然後完全卸載，之後重新加載直到外力為 V3，此時構架 產生的層間變位 Δ 約略等於(Δ2+Δ3)/2"], "answer": "C"}, {"number": 27, "prompt": "在鋼筋混凝土結構設計中，關於構材斷面之平衡應變狀態與平衡鋼筋比，下列敘述何者正確？", "options": ["平衡應變狀態為混凝土之最外受壓纖維達到混凝土抗壓強度之同時，最外側受拉鋼筋之應 變恰達到鋼筋材料的破壞應變值", "在設計矩形斷面的鋼筋混凝土單筋梁時，最理想的斷面鋼筋比是平衡鋼筋比", "當矩形斷面單筋梁的斷面鋼筋比大於平衡鋼筋比時，梁會出現混凝土壓碎而鋼筋未降伏的 脆性破壞模式", "當梁所承受的載重增加時，其平衡鋼筋比也會隨之增加 G B D F H A C E P G"], "answer": "B"}, {"number": 28, "prompt": "下圖為一歷史建築的結構示意圖。該建築物的外牆為磚牆，大廳柱為實心的圓形木柱，屋頂 則由木造桁架所搭建。磚牆底部埋入地下 0.5 公尺，大廳柱上端為鉸接、下端為鉸支承，木 造桁架屋頂兩側末端的節點直接架於磚牆上，屋頂末端節點與磚牆接觸面處的靜摩擦係數為 0.3。圖中的空心箭頭代表外部集中載重的施力點，結構構件本身的自重全部忽略。關於此建 築結構，下列敘述何者正確？ (i) (ii)", "options": ["此結構在水平方向為不穩定結構", "此結構為靜不定結構", "在圖(i)的外力作用下，該屋頂桁架內沒有任何的零力桿件（zero-force member）", "在圖(ii)的外力作用下，該屋頂桁架內有 2 根零力桿件（zero-force member）"], "answer": "C"}, {"number": 29, "prompt": "試分析下圖結構，下列剪力圖與彎矩圖何者正確？", "options": ["", "", "", ""], "answer": "C"}, {"number": 30, "prompt": "以下鋼結構斜撐系統中，何者側向勁度最高？", "options": ["", "", "", ""], "answer": "A"}, {"number": 31, "prompt": "如下圖所示的三鉸式剛構架，A、E 為鉸支承，C 為鉸接。此剛構架於 B 點承受 6 kN 之外力 作用。有關此剛構架的受力情況，下列敘述何者正確？", "options": ["Ax=3 kN(←)，Ay=3 kN(↓)，Ex=3 kN(←)，Ey=3 kN(↑)", "Ax=3 kN(←)，Ay=3 kN(↑)，Ex=3 kN(←)，Ey=3 kN(↑)", "Ax=3 kN(→)，Ay=3 kN(↑)，Ex=3 kN(←)，Ey=3 kN(↑)", "Cx=0 kN，Cy=0 kN"], "answer": "D"}, {"number": 32, "prompt": "下列何者不屬於鋼造梁構件可能之破壞模式？", "options": ["構件側向扭轉挫屈", "梁端與柱接面之銲接處撕裂破壞", "斷面局部挫屈", "腹板受剪均布斜向裂縫"], "answer": "B"}, {"number": 33, "prompt": "關於鋼梁桿件的鋼板「局部挫屈」，下列敘述何者錯誤？", "options": ["結實斷面之彎矩強度可以發揮至塑性彎矩，在此之前鋼板都不會產生局部挫屈", "腹板之寬厚比限制小於翼板", "寬厚比越小，局部挫屈強度越大", "若材料彈性係數 E 增大，則局部挫屈強度增加"], "answer": "C"}, {"number": 34, "prompt": "下列與鋼結構梁柱接頭相關敘述何者正確？", "options": ["鋼筋混凝土樓板對於接頭強度沒有影響", "梁受到正彎矩時，因為樓板的作用會使下翼板的應力大幅增加", "扇形開孔的形式對於接頭耐震性能沒有影響", "接頭區域的強度檢討僅需考慮柱梁強度比"], "answer": "D"}, {"number": 35, "prompt": "鋼筋混凝土抗彎矩構架系統有時會因設計或施工因素來加大梁寬尺寸，下列何者不會受梁寬 放大而影響？", "options": ["梁之拉力鋼筋總量限制", "梁柱構架之接頭剪力計算強度", "梁主筋於接頭內之彎鉤伸展長度", "梁主筋之施工性"], "answer": "D"}, {"number": 36, "prompt": "RC 結構特殊抗彎矩構架系統的韌性設計原則，下列敘述何者錯誤？", "options": ["梁之設計剪力強度應考慮兩端部最大的可能彎矩強度造成之剪力", "對於軸壓力達一定程度之柱，其上下柱之彎矩強度和應大於梁之彎矩強度和", "柱設計剪力應考慮柱上下端產生最大可能彎矩強度所計得之剪力", "梁柱構架之接頭，若接頭四面有梁構入的面數越多，其接頭的剪力計算強度越低"], "answer": "B"}, {"number": 37, "prompt": "下列何者須考量材料異向性對結構力學特性的影響？", "options": ["鋼筋混凝土結構", "鋼骨結構", "鋼骨鋼筋混凝土結構", "木造結構"], "answer": "C"}, {"number": 38, "prompt": "在拆解一梁柱式木構造擬重複使用構材時，發現多數桿件斷面部分受損，因此將所有桿件裁 切為較短、斷面較小之桿件。在儘量使用舊有桿件條件下，下列結構系統何者最適合用來搭 建接近原本跨距之結構？", "options": ["承重牆結構", "桁架", "大木構造與斗栱", "薄膜"], "answer": "B"}, {"number": 39, "prompt": "下列建築材料當中，何者最不符合永續綠建材的概念？", "options": ["複合木材（如：木塑材）", "鋼", "鋼筋混凝土", "砌石"], "answer": "A"}, {"number": 40, "prompt": "對於臺灣的 40～50 層超高層建築物，在一般狀況下，下列敘述何者錯誤？", "options": ["設計風力可能會大於設計地震力", "設計風力乘以載重因數後，若能大於設計地震力，則不用進行韌性設計", "一般強度的 RC 構造並不適用此樓層範圍", "純抗彎構架結構系統採用鋼骨造仍有困難"], "answer": "B"}], "questionCount": 40, "answerCount": 40}, {"year": "113", "subject": "建築法規", "officialSubject": "營建法規與實務", "durationMinutes": 120, "questions": [{"number": 1, "prompt": "依建築法規定，申請建造執照之建築物平面、立面、剖面圖，其比例尺最小不得小於多少？", "options": ["1/30", "1/50", "1/100", "1/200"], "answer": "D"}, {"number": 2, "prompt": "依建築法規定，直轄市、縣（市）（局）主管建築機關收到起造人申請建造執照書件之日起，至多應 於幾日內審查完竣，合格者即發給執照？", "options": ["5", "10", "15", "30"], "answer": "B"}, {"number": 3, "prompt": "依建築法規定，下列敘述何者正確？", "options": ["建築基地與建築線應相連接，其接連部分之最小寬度，由中央主管建築機關統一規定", "建築物基地地面，不得高出所臨接道路邊界處之路面", "建築基地最小面積之寬度及深度，由中央主管建築機關統一規定", "建築基地面積畸零狹小不合規定者，非與鄰接土地協議調整地形或合併使用，達到規定最小面積之 寬度及深度，不得建築"], "answer": "D"}, {"number": 4, "prompt": "依建築法規定，起造人領得建造執照後，應即申報該管主管建築機關備案之情事，不包含下列何者？", "options": ["變更起造人", "變更承造人", "變更設計人", "變更監造人"], "answer": "C"}, {"number": 5, "prompt": "依建築法規定，建築工程中必須勘驗部分，應由直轄市、縣（市）主管建築機關於核定建築計畫時， 指定由承造人會同下列何者按時申報後，方得繼續施工？", "options": ["設計人", "監造人", "起造人", "工地主任"], "answer": "B"}, {"number": 6, "prompt": "依建築法規定，建築工程部分完竣後可供獨立使用者，得核發下列何種執照？", "options": ["臨時使用執照", "部分使用執照", "雜項使用執照", "特種使用執照"], "answer": "B"}, {"number": 7, "prompt": "依建築法規定，建築物室內裝修應遵守之規定，不包含下列何者？", "options": ["供公眾使用建築物之室內裝修應申請審查許可", "不得妨害或破壞防火避難設施、消防設備、防火區劃及主要構造", "不得妨害或破壞保護民眾隱私權設施", "應由依法登記開業之建築師負責施工"], "answer": "D"}, {"number": 8, "prompt": "依建築法規定，主管建築機關對傾頹或朽壞有危害公共安全之建築物，除應通知所有權人或占有人停 止使用外，並限期命下列何者拆除？", "options": ["使用人", "占有人", "所有人", "承租人"], "answer": "C"}, {"number": 9, "prompt": "依違章建築處理辦法規定，舊違章建築在未依規定拆除或整理前，下列敘述何者正確？", "options": ["得准予修繕，但不得新建、增建、改建、修建", "得准予修繕或修建，但不得新建、增建、改建", "得准予修繕、修建或改建，但不得新建、增建", "不得修繕、新建、增建、改建、修建"], "answer": "A"}, {"number": 10, "prompt": "有關「室內裝修業」之管理規定，下列敘述何者錯誤？", "options": ["室內裝修業從事室內裝修設計業務者，應置有專業設計技術人員 1 人以上", "室內裝修業應先辦理公司或商業登記後，再向內政部申請室內裝修業登記許可並領得登記證。未領 得登記證者，不得執行室內裝修業務", "室內裝修業登記證有效期限為 4 年，逾期未換發登記證者，不得執行室內裝修業務", "室內裝修業受停業處分累計滿 3 年者，經當地主管建築機關查明屬實後，報請內政部廢止室內裝修 業登記許可並註銷登記證 代號：1801 頁次：8－2"], "answer": "C"}, {"number": 11, "prompt": "依建築師法規定，已充任建築師，得由中央主管機關撤銷或廢止其建築師證書之情形，不包含下列何者？", "options": ["受監護或輔助宣告，尚未撤銷", "罹患精神疾病或身心狀況違常，經中央主管機關委請 2 位以上相關專科醫師諮詢，並經中央主管機 關認定不能執行業務", "受破產宣告，尚未復權", "已喪失中華民國國籍"], "answer": "D"}, {"number": 12, "prompt": "依實施區域計畫地區建築管理辦法，於各種用地內申請建造自用農舍者，下列敘述何者錯誤？", "options": ["其總樓地板面積不得超過 495 平方公尺", "建築面積不得超過其耕地面積 10%", "建築物高度不得超過 3 層樓並不得超過 12 公尺", "最大基層建築面積不得超過 330 平方公尺"], "answer": "D"}, {"number": 13, "prompt": "依實施區域計畫地區建築管理辦法規定，申請建造農舍時，應填具申請書，並檢附下列書圖文件向當 地主管建築機關申請辦理，下列敘述何者錯誤？", "options": ["現耕農身分證明", "土地權利證明文件", "基地位置圖", "農舍配置圖，其比例尺不得小於 1/1500"], "answer": "B"}, {"number": 14, "prompt": "依實施區域計畫地區建築管理辦法規定，原有農舍之修建，改建或增建面積最多在多少平方公尺以下 之平房得免申請建築執照，但其建蔽率及總樓地板面積不得超過本辦法之有關規定？", "options": ["30", "45", "60", "90"], "answer": "D"}, {"number": 15, "prompt": "依建築物部分使用執照核發辦法，所稱建築工程部分完竣，下列敘述何者錯誤？", "options": ["二幢以上建築物，其中任一幢業經全部施工完竣", "連棟式建築物，其中任一棟業經施工完竣", "高度超過 36 公尺或 12 層樓以上，其中任一樓層至基地地面間各層業經施工完竣", "建築面積超過 6000 平方公尺以上之建築物，其中任一樓層至基地地面間各層業經施工完竣"], "answer": "B"}, {"number": 16, "prompt": "依原有合法建築物公共安全改善辦法規定，直通樓梯之設置及步行距離，增設之直通樓梯，下列敘述 何者錯誤？", "options": ["應為安全梯，且寬度應為 90 公分以上", "不計入建築面積及各層樓地板面積。但增加之面積不得大於原有建築面積 1/5 或 100 平方公尺", "不受鄰棟間隔、前院、後院及開口距離有關規定之限制", "高度不得超過原有建築物高度加 3 公尺，亦不受容積率之限制"], "answer": "A"}, {"number": 17, "prompt": "有關建築物辦理耐震能力評估檢查之規定，下列敘述何者錯誤？", "options": ["中華民國 88 年以前領得使用執照之建築物，免辦理耐震能力評估檢查", "供建築物使用類組 G-1、G-2 組使用之樓地板面積累計達 1000 平方公尺以上之建築物，得免辦理耐 震能力評估檢查", "供建築物使用類組 B-4 組使用之樓地板面積累計未達 1000 平方公尺以上之建築物，得免辦理耐震 能力評估檢查", "供建築物使用類組 A-1 組使用之樓地板面積累計達 1000 平方公尺以上之建築物，且該建築物同屬 一所有權人或使用人，應辦理耐震能力評估檢查"], "answer": "B"}, {"number": 18, "prompt": "有關建築物無障礙設施設計規範之無障礙樓梯級高（R）及級深（T），下列何者符合規定？", "options": ["級高（R）18 公分，級深（T）26 公分", "級高（R）16 公分，級深（T）26 公分", "級高（R）18 公分，級深（T）24 公分", "級高（R）16 公分，級深（T）24 公分"], "answer": "C"}, {"number": 19, "prompt": "有關開業建築師設立事務所執行業務，其開業登記方式及執行業務之區域規定，下列敘述何者正確？", "options": ["向內政部國土管理署辦理登記開業，且以全國為其執行業務之區域", "向內政部指定之直轄市、縣（市）辦理登記開業，且以登記之直轄市、縣（市）為其執行業務之區域", "逕向事務所所在地直轄市、縣（市）辦理登記開業，且以全國為其執行業務之區域", "逕向事務所所在地直轄市、縣（市）辦理登記開業，且以登記之直轄市、縣（市）為其執行業務之 區域 代號：1801 頁次：8－3"], "answer": "A"}, {"number": 20, "prompt": "依建築師法規定，建築師得受委託人委託辦理之業務，下列敘述何者錯誤？", "options": ["辦理建築物及其實質環境之調查、測量、鑽探、設計、監造", "辦理建築物及其實質環境之估價、檢查、鑑定業務", "得代委託人辦理申請建築許可、招商投標", "得代委託人辦理擬定施工契約及其他工程上之接洽事項"], "answer": "C"}, {"number": 21, "prompt": "依建築師法規定，直轄市、縣（市）主管機關對於建築師得予獎勵之事項，不包含下列何者？", "options": ["對建築法規、區域計畫或都市計畫襄助研究及建議，有重大貢獻者", "對公共安全、社會福利或預防災害等有關建築事項襄助辦理，成績卓著者", "對公共交通研究有卓越表現者", "對協助推行建築實務著有成績者"], "answer": "C"}, {"number": 22, "prompt": "依建築師法規定，建築師之懲戒處分，不包含下列何者？", "options": ["警告", "申誡", "停止執行業務 3 年以上", "撤銷開業證書"], "answer": "B"}, {"number": 23, "prompt": "下列何者非屬住宅法所規定主管機關應定期蒐集、分析及公布之住宅資訊？", "options": ["租賃與買賣住宅市場之供給、需求", "違章建築分布之範圍", "經濟或社會弱勢者之住宅補貼政策成效", "居住品質狀況"], "answer": "C"}, {"number": 24, "prompt": "依據建築技術規則總則編規定，直轄市、縣（市）主管建築機關因應地方特殊需求，得另訂設計、施 工、構造及設備規定並報經中央主管建築機關核定後實施之事項，不包括下列那一項？", "options": ["新建建築物有效日照之檢討方式", "震災毀損建築物拆除重建之設計規定", "建築物變更用途之檢討項目及標準", "新建建築物節約能源之檢討方式"], "answer": "C"}, {"number": 25, "prompt": "依建築技術規則規定，下列何者可以透過中央指定之專業機構完成評定並向中央主管建築機關申請認 可，得不適用本規則一部或全部之規定？", "options": ["無障礙設施設計", "有效日照設計", "防火避難設施設計", "安全維護設計"], "answer": "B"}, {"number": 26, "prompt": "依建築技術規則建築設計施工編用語定義之規定，有關於建築物屋面上設置附屬建築物及雜項工作物 與該建築物高度計算之關係，下列敘述何者錯誤？", "options": ["於屋面上設置樓電梯間，其設計之高度及面積，與該建築物之高度計算有關", "於屋面上設置管道間，其設計之高度及面積，與該建築物之高度計算有關", "於屋面上設置雨水貯留利用設備，其設計之高度及面積，均與建築物之高度計算無關", "於屋面上設置再生能源節能設施，其設計之高度及面積，均與建築物之高度計算無關"], "answer": "C"}, {"number": 27, "prompt": "依建築技術規則規定，防火構造建築物無法區劃分隔部分，以具 1 小時防火時效之牆壁、防火門窗等 防火設備與該處防火構造之樓板自成 1 個區劃者，不受樓地板面積每 1500 平方公尺作一區劃之限制， 不包括下列何種用途建築物？", "options": ["工廠類生產線部分", "體育館", "電影院的美食街", "零售市場"], "answer": "B"}, {"number": 28, "prompt": "某建築物屬 H-1 組之產後護理機構，除避難層外各樓層應以具 1 小時以上防火時效之牆壁及防火設備 分隔為 2 個以上之區劃，前述區劃之樓地板面積至少不得小於同樓層另一區劃之樓地板面積比例為 多少？", "options": ["1/2", "1/3", "1/4", "1/5"], "answer": "B"}, {"number": 29, "prompt": "依建築技術規則規定，有關特別安全梯之構造，下列敘述何者錯誤？", "options": ["樓梯間及排煙室之四周牆壁應具有 1 小時以上防火時效", "天花板及牆面之裝修應為耐燃 3 級以上之材料", "管道間之維修孔不得開向樓梯間", "樓梯間與排煙室之間所開設之窗戶應為固定窗"], "answer": "D"}, {"number": 30, "prompt": "依建築技術規則規定，下列何種空間無設置建築物安全維護裝置之規定？", "options": ["停車空間", "安全梯間", "避難層出入口", "昇降機間 代號：1801 頁次：8－4"], "answer": "B"}, {"number": 31, "prompt": "依建築技術規則規定，有關安全梯構造之敘述，下列何者錯誤？", "options": ["特別安全梯自陽臺進入樓梯間之出入口之防火門應具半小時以上防火時效", "戶外安全梯出入口防火門應具半小時以上防火時效及半小時以上阻熱性", "進入室內安全梯之出入口，應裝設具 1 小時以上防火時效及半小時以上阻熱性且具遮煙性能之防火門", "戶外安全梯以室外走廊連接安全梯者其出入口免裝設防火門"], "answer": "C"}, {"number": 32, "prompt": "依建築技術規則規定，政府機關及公私團體辦公廳，總樓地板面積至少超過多少平方公尺屬特定建築物？", "options": ["300", "500", "1000", "3000"], "answer": "B"}, {"number": 33, "prompt": "依建築技術規則建築設計施工編規定，新建或增建建築物高度超過 21 公尺部分，在冬至日所造成之 日照陰影，應使鄰近之住宅區或商業區基地有 1 小時以上之有效日照。下列敘述何者錯誤？", "options": ["新建基地內僅配置單幢建築物，且其投影於北向面寬不超過 10 公尺者，得免檢討有效日照", "新建基地內配置兩幢建築物，投影於北向最大面寬合計超過 20 公尺，如均已自基地北向境界線退 縮 6 公尺，檢討有效日照時，兩幢得個別檢討", "新建基地內配置兩幢建築物，投影於北向最大面寬合計超過 20 公尺，相鄰間最外緣部位連線角度 未達 12.5 度，檢討有效日照時，兩幢應合併檢討", "檢討有效日照時，得不包括未計入建築面積之部分"], "answer": "D"}, {"number": 34, "prompt": "建築技術規則有關無障礙建築物之規定，下列敘述何者錯誤？", "options": ["新建或增建建築物，應依規定設置無障礙設施，但供住宅使用之公寓大廈專有及約定專用部分者， 不在此限", "新建或增建建築物，應依規定設置無障礙設施，但建築基地面積未達 200 平方公尺者，或每棟每層 樓地板面積均未達 100 平方公尺，不在此限", "新建或增建建築物，應依規定設置無障礙設施時，建築物設置之直通樓梯，至少應有 1 座為無障礙 樓梯", "新建或增建建築物，應依規定設置無障礙設施時，建築物設有共用浴室者，每幢建築物至少應設置 一處無障礙浴室"], "answer": "C"}, {"number": 35, "prompt": "依建築技術規則規定，下列何種建築物在新建時，不需要檢討建築物節約能源項目？", "options": ["學校類", "大型空間類", "住宿類", "作業廠房"], "answer": "B"}, {"number": 36, "prompt": "依建築技術規則規定，除衛生醫療類（F-1 組）或經中央主管建築機關認可之建築物外，其總樓地板 面積最少達多少平方公尺以上之新建建築物，應適用建築物雨水或生活雜排水回收再利用項目之檢討？", "options": ["4000", "6000", "10000", "12000"], "answer": "D"}, {"number": 37, "prompt": "依建築技術規則規定，建築基地保水指標至少應大於下列那一係數與基地內應保留法定空地比率之 乘積？", "options": ["0.4", "0.5", "0.8", "1.0"], "answer": "D"}, {"number": 38, "prompt": "依建築技術規則建築構造編，有關鋼骨鋼筋混凝土構造施工之規定，下列敘述何者錯誤？", "options": ["鋼骨鋼筋混凝土構造之施工，應依施工規範規定", "鋼骨鋼筋混凝土工程之混凝土澆置，應注意其填充性，並應避免混凝土骨材析離", "鋼骨鋼筋混凝土構造之施工過程中任何階段之結構強度及穩定性，應於施工前審慎評估，以確保施 工過程中安全無慮", "鋼骨鋼筋混凝土構造之施工，需在鋼骨斷面上穿孔時，其穿孔及補強，應在施工現場內施作完成"], "answer": "A"}, {"number": 39, "prompt": "下列何者非屬農業用地興建農舍辦法規定申請興建農舍之條件？", "options": ["申請人應為農民，已成年者", "申請興建農舍之該筆農業用地面積不得小於 0.25 公頃。但參加興建集村農舍及於離島地區興建農 舍者，不在此限", "申請人為該農業用地之所有權人，且該農業用地應確供農業使用及屬未經申請興建農舍者；該農舍 之興建並不得影響農業生產環境及農村發展", "申請人參加興建集村農舍建築物坐落之農業用地，其土地取得及戶籍登記均應滿 2 年 代號：1801 頁次：8－5"], "answer": "A"}, {"number": 40, "prompt": "市鎮計畫應先擬定主要計畫書。有關都市計畫法規定主要計畫書應載明之事項，下列何者錯誤？", "options": ["主要計畫書其實施進度以 3 年為一期，最長不得超過 30 年", "名勝、古蹟及具有紀念性或藝術價值應予保存之建築", "人口之成長、分布、組成、計畫年期內人口與經濟發展之推計", "實施進度及經費"], "answer": "C"}, {"number": 41, "prompt": "依都市計畫法規定，下列何者非更新計畫應表明之事項？", "options": ["人口之成長、分布、組成、計畫年期內人口與經濟發展之推計", "土地使用計畫", "劃定地區內重建、整建及維護地段之詳細設計圖說", "區內公共設施興修或改善之設計圖說"], "answer": "D"}, {"number": 42, "prompt": "有關都市計畫法規定之組織與經費，下列敘述何者錯誤？", "options": ["中央、直轄市或縣（市）政府為實施都市計畫或土地徵收，得發行公債", "內政部、各級地方政府及鄉、鎮、縣轄市公所為審議及研究都市計畫，應分別設置都市計畫委員會 辦理之", "都市計畫委員會之組織，由直轄市或縣（市）政府定之", "內政部、各級地方政府及鄉、鎮、縣轄市公所應設置經辦都市計畫之專業人員"], "answer": "B"}, {"number": 43, "prompt": "有關都市更新條例用語之敘述，下列何者正確？", "options": ["都市更新：在都市計畫範圍或非都市土地，實施重建、整建或維護措施", "實施者：實施都市更新事業之機關、機構、團體或自然人", "重建：拆除更新單元內原有建築物，重新建築，並不得變更其土地使用性質或使用密度", "整建：改建、修建更新單元內建築物或充實其設備，並改進區內公共設施"], "answer": "D"}, {"number": 44, "prompt": "依都市更新條例規定，下列敘述何者錯誤？", "options": ["都市更新計畫係指依都市更新條例規定程序，載明更新地區應遵循事項，作為擬訂都市更新事業計 畫之指導", "都市更新事業僅得以重建、整建或維護其中一種處理方式為之", "更新單元係指可單獨實施都市更新事業之範圍", "直轄市、縣（市）主管機關得優先將建築物未符合都市應有機能之地區劃定為更新地區"], "answer": "B"}, {"number": 45, "prompt": "依都市更新條例規定，對於都市更新公開評選申請及審核程序之爭議申訴，下列何者錯誤？", "options": ["依主辦機關屬中央或地方機關（構），分別由中央或直轄市、縣（市）主管機關設都市更新公開評 選申訴審議會處理", "申訴人誤向該管都更評選申訴會以外之機關申訴者，以該機關收受日，視為提起申訴之日", "申訴逾法定期間或不合法定程序者，不予受理。但其情形得予補正者，應定期間命其補正；屆期不 補正者，不予受理", "申訴提出後，申請人得於審議判斷送達前撤回之。申訴經撤回後，僅得再提出同一申訴一次"], "answer": "B"}, {"number": 46, "prompt": "依都市計畫容積移轉實施辦法規定，非屬位於整體開發地區、實施都市更新地區、面臨永久性空地或 其他都市計畫指定地區範圍內接受基地之可移入容積，以不超過該接受基地基準容積百分之多少為原 則？", "options": ["20", "30", "40", "50"], "answer": "C"}, {"number": 47, "prompt": "依都市更新條例規定，有關權利變換之敘述，何者錯誤？", "options": ["權利變換計畫書核定發布實施後 2 個月內，土地所有權人對其權利價值有異議時，應以書面敘明理 由，向各級主管機關提出", "異議處理或行政救濟期間，應停止都市更新事業之進行", "異議處理或行政救濟結果與原評定價值有差額部分，由當事人以現金相互找補", "審議核復期限，應扣除各級主管機關委託專業團體或機構協助作技術性諮商及實施者委託專業團體 或機構重新查估權利價值之時間 代號：1801 頁次：8－6"], "answer": "A"}, {"number": 48, "prompt": "依國土計畫法規定，國土計畫中央主管機關應設置國土永續發展基金，下列何者屬基金來源之一？", "options": ["使用許可案件所收取之國土影響費", "工程受益費", "本基金孳息收入", "土地增值稅之提撥"], "answer": "C"}, {"number": 49, "prompt": "依國土計畫法規定，國土永續發展基金來源，有關政府之撥款方式，下列何者錯誤？", "options": ["直轄市、縣（市）主管機關應視檢討變更情形逐年編列預算移撥", "國土計畫施行後 10 年，移撥總額不得低於新臺幣 500 億元", "基金來源有關自來水、電力事業機構附徵之一定比率費用來源，自國土計畫法施行後第 11 年起適用", "上述自來水、電力事業機構附徵費用，其附徵項目、一定比率之計算等相關事項之辦法，由中央主 管機關定之"], "answer": "C"}, {"number": 50, "prompt": "依國土計畫法規定，國土復育計畫之擬定及定期檢討，下列何者正確？", "options": ["國土復育促進地區經劃定者應以保育和適度開發行為及設施之設置兩者併行為原則", "由劃定機關擬定復育計畫報請中央主管機關核定後實施", "復育計畫每 5 年應通盤檢討一次", "復育計畫核定實施後如有變更需要，得隨時報請原核定之中央主管機關核准變更"], "answer": "C"}, {"number": 51, "prompt": "依國土計畫法規定，下列何者不是都會區域規劃基本原則？", "options": ["應配合區域特色與整體發展需要", "加強跨域整合，達成資源互補", "尊重及保存原住民族傳統文化", "強化區域機能提升競爭力"], "answer": "D"}, {"number": 52, "prompt": "依國土計畫法規定，土地於符合國土功能分區使用及其分類之使用原則下，得申請使用許可。其程序 下列何者正確？", "options": ["使用許可之申請由中央主管機關受理", "申請許可範圍屬國土保育地區或海洋資源地區者，由直轄市、縣（市）主管機關審議", "申請許可範圍跨二個直轄市、縣（市）行政區以上者，由中央主管機關審議", "填海造陸案件者由直轄市、縣（市）主管機關審議"], "answer": "B"}, {"number": 53, "prompt": "下列何者是直轄市、縣（市）國土計畫審議會應辦理事項？", "options": ["國土復育促進地區之劃定及擬訂復育計畫之審議", "國土保育地區之使用許可、許可變更及廢止之審議", "海洋資源地區之使用許可、許可變更及廢止之審議", "農業發展地區之使用許可、許可變更及廢止之審議"], "answer": "C"}, {"number": 54, "prompt": "下列何者非屬公寓大廈管理條例所稱之「住戶」？", "options": ["承租人", "未經區分所有權人同意而為專有部分之使用者", "區分所有權人", "業經取得停車空間建築物所有權者"], "answer": "D"}, {"number": 55, "prompt": "依區域計畫法規定，中央、直轄市、縣（市）主管機關為推動區域計畫之實施及區域公共設施之興修， 得組成區域建設推行委員會。其任務包含下列何者？", "options": ["有關區域計畫之審查事項", "有關區域開發建設事業計畫之審查事項", "有關個別開發建設事業之協調事項", "有關籌措區域公共設施建設經費之審查事項"], "answer": "D"}, {"number": 56, "prompt": "依國家公園法規定，一般管制區或遊憩區內，經國家公園管理處之許可，得為下列何種行為？", "options": ["焚燬草木或引火整地", "狩獵動物或捕捉魚類", "採折花木", "礦物或土石之勘採"], "answer": "C"}, {"number": 57, "prompt": "依國土計畫法規定，填海造地案件限於何種國土功能分區始得申請？", "options": ["國土保育地區", "海洋資源地區", "農業發展地區", "城鄉發展地區"], "answer": "C"}, {"number": 58, "prompt": "直轄市、縣（市）政府得組設公寓大廈爭議事件調處委員會，下列何者非屬應不予受理調處事項？", "options": ["當事人無從通知者", "調處事件不屬受理機關管轄者", "管理委員會未執行區分所有權人會議決議事項", "已訴請法院審理中或經法院和解、調解或判決確定者 代號：1801 頁次：8－7"], "answer": "A"}, {"number": 59, "prompt": "營造業法所稱營造業，不包括下列何者？", "options": ["綜合營造業", "專業營造業", "電氣水管業", "土木包工業"], "answer": "D"}, {"number": 60, "prompt": "營造業法所稱資本額，於營造業以股份有限公司設立者，係指下列何者？", "options": ["實收資本額", "應收資本額", "登記資本額", "交易資本額"], "answer": "D"}, {"number": 61, "prompt": "依文化資產保存法規定，下列何者非屬古蹟之管理維護事項？", "options": ["日常保養及定期維修", "使用或再利用經營管理", "緊急應變計畫之擬定", "建築物拆除應注意事項"], "answer": "C"}, {"number": 62, "prompt": "依營造業法規定，下列敘述何者錯誤？", "options": ["營造業負責人不得為其他營造業之負責人、專任工程人員或工地主任", "技術士應於工地現場依其專長技能及作業規範進行施工操作或品質控管", "營造業之工地主任應負責辦理工作包括依施工計畫書執行按圖施工", "營造業之專任工程人員應負責辦理工作包括按日填報施工日誌"], "answer": "A"}, {"number": 63, "prompt": "依政府採購法規定，投標廠商有下列何種情形，機關應不予開標或不予決標？①借用或冒用他人名義 或證件投標 ②不同投標廠商間之投標文件內容有重大異常關聯 ③服務建議書頁數太少 ④以不 實文件投標", "options": ["僅①②③", "僅②③④", "僅①②④", "①②③④"], "answer": "C"}, {"number": 64, "prompt": "依政府採購法相關規定，查核小組查核結果，有下列何種情況之一者，應列為丙等？", "options": ["混凝土結構物鑽心試體試驗結果不合格", "人行道工程破損", "室內輕隔間框架間距不足", "粉刷不平整"], "answer": "D"}, {"number": 65, "prompt": "依採購評選委員會組織準則規定，評選委員會召集人由誰擔任？", "options": ["委員互推一人擔任", "專家學者委員互推一人擔任", "機關首長擔任，或由機關首長或其授權人員指定一級主管以上人員擔任", "工作小組組長擔任"], "answer": "B"}, {"number": 66, "prompt": "依政府採購法規定，有關機關辦理採購之招標方式，下列敘述何者正確？", "options": ["皆應經過公告方式，以確保公平公開之原則", "皆應秘密為之，以利採購程序順利", "可不經公告方式預先依一定資格條件辦理廠商資格審查後，依選擇性招標辦理，以簡化程序", "限制性招標係指不經公告程序，邀請二家廠商以上比價或僅邀請一家廠商議價"], "answer": "A"}, {"number": 67, "prompt": "依建築物無障礙設施設計規範規定，無障礙坡道至少每高差多少公分，應設置 150 公分以上且坡度不 得大於 1/50 之平台？", "options": ["60", "75", "90", "100"], "answer": "B"}, {"number": 68, "prompt": "有關無障礙昇降機機門設有可自動停止並重新開啟的裝置，下列敘述何者正確？", "options": ["該裝置是讓門遇到物體或人阻礙時的安全設計", "該裝置主要是方便搬運大型物件的安全設計", "昇降機開門時，昇降機門應維持完全開啟狀態至少 3 秒鐘", "昇降機出入口處之地板面，應與靜止時之機廂地板面保持不得大於 5 公分之高低差"], "answer": "C"}, {"number": 69, "prompt": "有關無障礙設施「輪椅觀眾席位」之規定，下列何者錯誤？", "options": ["由前方進入之輪椅觀眾席位，深度應為 120 公分以上", "由後方進入之輪椅觀眾席位，深度應為 100 公分以上", "僅可由右側面進入者，深度應為 150 公分以上", "僅可由左側面進入者，深度應為 150 公分以上"], "answer": "B"}, {"number": 70, "prompt": "依建築物無障礙設施設計規範規定，輪椅觀眾席之地面應平整、防滑、易於通行，且坡度至多不得大 於多少？", "options": ["1/30", "1/40", "1/50", "1/60 代號：1801 頁次：8－8"], "answer": "C"}, {"number": 71, "prompt": "依建築物無障礙設施設計規範之輪椅觀眾席位規定，下列敘述何者錯誤？", "options": ["輪椅觀眾席位得設於觀眾席不同位置、區域及樓層", "中間區塊之席位與銀幕兩側之夾角沒有角度限制", "兩側區塊之席位與銀幕兩側之夾角不得大於 60°", "席位之水平視線與觀看銀幕中心視線之夾角不得大於 30°"], "answer": "D"}, {"number": 72, "prompt": "依建築物無障礙設施設計規範之無障礙客房規定，下列敘述何者錯誤？", "options": ["無障礙客房內應設置衛浴設備，衛浴設備至少應包括馬桶、洗面盆及浴缸或淋浴間等", "衛浴設備空間應設置直徑 135 公分以上之迴轉空間", "衛浴設備之迴轉空間邊緣 30 公分範圍內如符合膝蓋淨容納空間規定者，得納入迴轉空間計算", "求助鈴應連接至服務台或類似空間，若無服務台，應連接至該客房外部之警示燈或聲響"], "answer": "C"}, {"number": 73, "prompt": "縣市政府受理人民聲請許可案件適用法規時，下列何者錯誤？", "options": ["依其性質應適用行為時之法規", "在處理程序終結前，據以准許之法規有變更者，適用新法規", "舊法規有利於當事人而新法規未廢除或禁止所聲請之事項者，適用舊法規", "新舊法規之適用由主管機關決定"], "answer": "B"}, {"number": 74, "prompt": "依建築物無障礙設施設計規範之無障礙客房規定，下列敘述何者錯誤？", "options": ["無障礙客房內通路寬度不得小於 120 公分", "無障礙客房內床間淨寬度不得小於 90 公分", "供房客使用之電器插座及開關：應設置於自地板面起算至 150 公分範圍內", "無障礙客房內求助鈴應至少設置 2 處"], "answer": "D"}, {"number": 75, "prompt": "依中央法規標準法規定，下列敘述何者錯誤？", "options": ["法規應規定施行日期，或授權以命令規定施行日期", "法規明定自公布或發布日施行者，自公布或發布之日起算至次日起發生效力", "法規特定有施行日期，或以命令特定施行日期者，自該特定日起發生效力", "法規定有施行區域或授權以命令規定施行區域者，於該特定區域內發生效力"], "answer": "B"}, {"number": 76, "prompt": "依住宅法規定之經濟或社會弱勢者身分，係指家庭總收入平均分配全家人口之金額及家庭財產，未超 過主管機關公告之一定標準，且應符合特定身分規定者，所稱特定身分不包含下列何者？", "options": ["65 歲以上之老人", "低收入戶", "災民", "育有未成年子女 1 人以上"], "answer": "B"}, {"number": 77, "prompt": "依住宅法施行細則規定，直轄市、縣（市）主管機關，應定期查核接受自建、自購、修繕住宅貸款利 息補貼或承租住宅租金補貼者家庭成員擁有住宅狀況，其定期查核之頻率，下列何者正確？", "options": ["應每半年查核 1 次，並得視需要隨時辦理", "應每 1 年查核 1 次，並得視需要隨時辦理", "應每 2 年查核 1 次，並得視需要隨時辦理", "應每 3 年查核 1 次，並得視需要隨時辦理"], "answer": "C"}, {"number": 78, "prompt": "依都市危險及老舊建築物建築容積獎勵辦法規定，建築物取得耐震設計標章，其容積獎勵額度為基準 容積百分之多少？", "options": ["5", "10", "15", "20"], "answer": "B"}, {"number": 79, "prompt": "依都市危險及老舊建築物加速重建條例施行細則規定，下列何者非屬重建計畫應載明事項？", "options": ["土地使用分區", "經依法登記開業建築師簽證之建築物配置及設計圖說", "公共設施改善計畫構想", "申請容積獎勵項目及額度"], "answer": "C"}, {"number": 80, "prompt": "依農業用地興建農舍辦法規定，直轄市主管機關為辦理申請興建農舍之核定作業，得由農業單位邀集 各單位組成審查小組，下列那個單位非在邀請範圍？", "options": ["環境保護", "財政", "地政", "都市計畫"], "answer": "D"}], "questionCount": 80, "answerCount": 80}, {"year": "113", "subject": "建築結構", "officialSubject": "建築結構", "durationMinutes": 120, "questions": [{"number": 1, "prompt": "下圖（左）為一簡支梁在均布荷載 q(x)作用下之示意圖，圖（右）則為該梁於 x 處截取一小 段梁 dx 之自由體圖。圖中 M 代表彎矩、dM 代表彎矩增量、V 代表剪力、dV 代表剪力增量。 下列關係式中，何者正確？", "options": ["dM/dV = dx", "dM/dx = q(x)", "dM/dx = V(x)", "dV/dx = M(x)"], "answer": "C"}, {"number": 2, "prompt": "一簡支梁斷面寬 100 mm，深度 150 mm，所在某一位置斷面的彎矩 100 kN-m，關於此斷面的 敘述，下列何者正確？", "options": ["斷面模數 S = 325 cm3", "斷面慣性矩 I = 2100 cm4", "斷面最大應力為 266.7 MPa", "斷面最小應力為-310.5 MPa"], "answer": "C"}, {"number": 3, "prompt": "關於薄殼結構，下列敘述何者錯誤？", "options": ["可分為可展開與不可展開薄殼", "無法以直線模板釘作薄殼", "切面曲率可為零", "雙曲拋物面薄殼又可稱為 HP 薄殼"], "answer": "B"}, {"number": 4, "prompt": "下列材料性質之敘述何者正確？", "options": ["材料楊氏係數（Young’s modulus）為材料應力－應變曲線圖中座標原點至極限點（Ultimate point）之斜率", "韌性材料（Ductile material）破壞時會吸收較多能量", "鋼材料頸縮（Necking）現象通常是發生在最大強度點之前", "極限點（Ultimate point）越接近降伏點（Yield point）之材料，破壞時能吸收較多能量"], "answer": "B"}, {"number": 5, "prompt": "關於纜索結構（cable structures）的敘述，下列何者錯誤？", "options": ["單曲率（single-curvature）結構的穩定性會優於雙曲率（double-curvature）結構", "雙索（double-cable）結構的穩定性會優於單索（single-cable）結構", "雙索結構中，曲率凹向上的纜索為主索，負責承擔大部分的荷載", "纜索內應施加預張力"], "answer": "A"}, {"number": 6, "prompt": "下列關於提高纜索結構（cable structures）穩定性的策略，何者無效？", "options": ["在與主索同一垂直平面內，增設一條曲率與主索相反的副索，且將主索與副索以拉力構件 或壓力構件相連接", "在曲率為凹向上的纜索下方增設錨定至地面的拉纜", "在纜索內施加較高的預張力", "降低纜索承擔的重力荷載 代號：80120 頁次：8－3"], "answer": "D"}, {"number": 7, "prompt": "在進行高層建築物結構設計時，下列敘述何者錯誤？", "options": ["於兩道連通到底的 RC 剪力牆間逐層設置水平短梁將兩道牆相連時，短梁稱為剪力連桿 （shear-link），在地震時會優先受損，具有消能作用", "使用對稱型的平面配置可降低扭轉變形，並避免應力集中", "於部分框架中各層增設斜撐有利於提高建築物抗震能力", "大量增設厚實結構牆可提高自振週期，有助於減低地震力"], "answer": "D"}, {"number": 8, "prompt": "關於設計載重組合，下列敘述何者正確？", "options": ["載重係數均大於或等於 1", "在同一個載重組合中，需同時考慮風力與地震力", "在靜載重 DL+活載重 LL 的組合中，靜載重的載重係數大於活載重", "載重組合中，載重係數可以為負值"], "answer": "D"}, {"number": 9, "prompt": "依「建築物耐震設計規範」，下列有關地震加速度反應譜之敘述何者正確？", "options": ["耐震設計規範中的加速度反應譜目的是用來規範建築物的形狀", "設計加速度反應譜對應至 475 年回歸期之地震", "目前加速度反應譜中，工址分成強、中、弱三個分區", "針對加速度反應譜「建築技術規則構造篇」亦有詳細規定"], "answer": "B"}, {"number": 10, "prompt": "結構系統中，柱應以直通至基礎為原則，若因配置困難而無法直通，造成梁上柱之問題時， 此類地震力傳遞路徑不連續處的梁構材，依據「建築物耐震設計規範」的精神，下列敘述何 者錯誤？", "options": ["梁上柱之接合構件彎矩強度應以強梁弱柱的原則設計", "支撐不連續構架之支撐構材，為避免先在此處產生塑鉸或破壞，地震力引致之內力應提高 1.4 αy 倍設計", "梁之彎矩設計應將梁上柱底彎矩強度一併納入分析", "支承梁之設計剪力強度應小於彎矩強度計得之剪力"], "answer": "D"}, {"number": 11, "prompt": "關於建築結構行為之敘述，下列何者錯誤？", "options": ["活載重與靜載重僅作用於垂直方向，地震力與風力僅作用於水平方向", "鋼筋混凝土結構受水平地震力作用時，柱的撓曲裂縫通常位於柱頭與柱腳處", "建築物各層樓板通常可假設為剛性樓板，但樓板較細長時，則應視為非剛性樓板", "計算鋼骨鋼筋混凝土結構之構材強度時，通常不考慮鋼骨的局部挫屈"], "answer": "A"}, {"number": 12, "prompt": "非結構物耐震考量，下列敘述何者錯誤？", "options": ["圖書館書架若無抗震措施，極易於強震中受損", "懸吊天花板因重量輕，不須考量耐震", "配電盤、水塔等均屬非結構物", "非結構物的震損會影響建築物使用機能"], "answer": "B"}, {"number": 13, "prompt": "下列關於建築物所使用被動消能元件之敘述，何者錯誤？", "options": ["消能元件概分為位移型、速度型與其它型式", "加裝消能元件之建築物，可放寬本身結構系統之限制高度", "消能建築設計基本原則之一為：對所有消能建築，要求在中小度地震下須完全保持彈性， 且非結構元件無明顯損壞", "位移型消能元件的受力與位移關係，主要為該元件兩端點相對位移的函數 代號：80120 頁次：8－4"], "answer": "D"}, {"number": 14, "prompt": "一般建築結構耐震設計時，下列敘述何者錯誤？", "options": ["結構物之耐震設計通常應兼顧強度及韌性", "若將結構物設計成大地震時仍保持彈性，殊不經濟", "地震設計橫力是將大地震引致的彈性地震力加以折減而得", "為使結構物具有韌性，提高結構材料強度是最好的作法"], "answer": "B"}, {"number": 15, "prompt": "有關建築結構耐震性質的敘述，下列何者錯誤？", "options": ["建築物的耐震性可根據強度和韌性來評價，韌性低的建築物必須將強度提高", "結構體的強度、韌性相同時，一般而言，將建築物整體加重可提升其耐震性", "高層建築為了應付長週期地震，可導入消能元件", "低矮鋼筋混凝土校舍，採用翼牆補強，一般而言可提高其強度"], "answer": "A"}, {"number": 16, "prompt": "一剛架結構受外力作用如圖所示，下列何種梁上塑性鉸產生時，不會形成不穩定結構？", "options": ["cf 兩點產生塑鉸", "cef 三點產生塑鉸", "cdf 三點產生塑鉸", "ijk 三點產生塑鉸"], "answer": "B"}, {"number": 17, "prompt": "圖示之二懸臂梁，短梁與長梁於 a 點之垂直變位量分別為 Δ1 與 Δ2，兩者關係可表示為 Δ1 = βΔ2， 則 β 為何？", "options": ["1/2", "1/4", "1/6", "1/8"], "answer": "D"}, {"number": 18, "prompt": "格子梁系統中，兩直交梁的斷面相同且端點支承亦相同。若直向與橫向的跨距比為 1：2，則 直向梁與橫向梁的勁度比為何？", "options": ["1：2", "2：1", "1：8", "8：1"], "answer": "C"}, {"number": 19, "prompt": "某懸臂梁長 3 m，承受均布載重 w。今將長度改為 6 m，仍承受均布載重 w，其他條件不變， 則此梁之自由端變位為原來梁之幾倍？", "options": ["4", "8", "16", "32"], "answer": "A"}, {"number": 20, "prompt": "根據尤拉挫屈公式（Euler equation），下列何種作法可降低柱子的有效長度，以提高柱子的挫屈 載重？①桿件中間增加側向支撐 ②增加柱端點束制 ③增加柱斷面 ④增加材料彈性係數", "options": ["僅①②", "僅①③", "僅①②③", "①②③④"], "answer": "B"}, {"number": 21, "prompt": "下列四種開口牆，其材料、外周尺寸、開口面積均相同，但開口位置或方式不同，何者抗震 強度最佳？", "options": ["", "", "", ""], "answer": "D"}, {"number": 22, "prompt": "下列那種牆設計對於建築物耐震時水平強度的提升效果最好？ 圖中以網點圖樣填滿的部分為牆體的範圍，白色部分則為開口（門或窗）", "options": ["結構牆(i)", "結構牆(ii)", "結構牆(iii)", "結構牆(iv)"], "answer": "A"}, {"number": 23, "prompt": "土壤液化會造成完工後的建築物下陷或傾斜，下列針對土壤液化現象的敘述，何者錯誤？", "options": ["觸發土壤液化的條件之一是建築物基礎底面的土壤承載力低，因此黏性土壤多的地層即屬 於土壤液化高風險區", "觸發土壤液化的條件之一是該地土質為疏鬆的砂質土壤。在此類土層上興建建築物前，若 以重物重複錘擊地面夯實土壤，即可降低日後發生土壤液化的機會", "觸發土壤液化的條件之一是土壤含水量達飽和狀態，因此在連日大雨過後，發生土壤液化 的機率會上升", "觸發土壤液化的條件之一是土壤受到擾動，因此土壤液化時常發生在強震過後"], "answer": "A"}, {"number": 24, "prompt": "在靜態條件下，擋土牆可能之破壞型式不包括下列何者？", "options": ["牆背或牆基礎下土壤液化導致破壞", "滑動破壞", "傾覆（前傾或後傾）破壞", "基礎承載破壞"], "answer": "B"}, {"number": 25, "prompt": "下圖剛架受地震力，最少出現幾個塑鉸時會發生崩塌？", "options": ["3 個", "4 個", "6 個", "7 個 代號：80120 頁次：8－6"], "answer": "D"}, {"number": 26, "prompt": "如圖所示之構架承受側力 P，兩柱分別高 L 及 2 L ，柱頂皆為鉸接（pin），兩柱 EI 值相同， 而梁為剛體。若假設柱水平變形主要為撓曲造成，剪力變形極小，則兩柱所分配水平剪力較 大者約為較小者之幾倍？", "options": ["1", "2", "4", "8"], "answer": "A"}, {"number": 27, "prompt": "下圖所示桁架中，a、c 兩桿互相垂直，在圖示水平力 P 作用下，那些桿件可能因受壓而產生 挫屈？", "options": ["僅 c", "ac", "acd", "abcd"], "answer": "D"}, {"number": 28, "prompt": "於「建築物混凝土結構設計規範」中，有關純混凝土之規定，下列敘述何者錯誤？", "options": ["於純混凝土結構構材的設計中，可使用混凝土的抗拉強度", "韌性並非純混凝土結構設計之基本需求", "純混凝土不可用於柱或樁帽", "純混凝土的抗剪強度通常與抗壓強度成正比"], "answer": "D"}, {"number": 29, "prompt": "關於預力混凝土梁之敘述，下列何者錯誤？", "options": ["預力混凝土梁使用預力鋼鍵，於構材受設計載重作用前先使混凝土處於受壓狀態，受設計 載重後通常不使混凝土發生拉應力", "預力混凝土梁承受過大載重而產生細微裂縫，當載重除去後裂縫將會閉合", "建築設計可採用預力混凝土梁取得較大之柱跨距", "依施工順序可分為先拉預力法及後拉預力法，兩者皆必須使用端錨來保持預力鋼鍵的錨定力"], "answer": "A"}, {"number": 30, "prompt": "關於鋼筋混凝土梁桿件之「平衡鋼筋比」，下列敘述何者錯誤？", "options": ["「平衡鋼筋比」係將平衡應變狀態之鋼筋量除以全斷面積", "梁桿件因斷面彎矩造成受壓處最外緣混凝土壓碎時（ε = 0.003），受拉側最外緣鋼筋剛好降伏", "韌性設計最大鋼筋比 ρmax 會小於平衡鋼筋比 ρb", "平衡鋼筋比 ρb 為一無因次單位 代號：80120 頁次：8－7"], "answer": "A"}, {"number": 31, "prompt": "關於鋼筋混凝土結構之敘述，下列何者錯誤？", "options": ["混凝土抗壓強度高、抗拉強度低，因此承受軸壓力愈大之柱，其韌性愈高", "地震時梁構材的兩端應力較大，梁上的管路貫穿孔通常設置於跨度中央，以避免降低梁的 耐震韌性", "一般而言，將與柱連接之梁寬加大，可使梁柱接頭區之剪力強度變大", "於耐震設計時，應使構材在剪力破壞前先產生彎曲降伏，以確保柱及梁之韌性"], "answer": "A"}, {"number": 32, "prompt": "下列何者有助於提升鋼筋混凝土結構韌性？", "options": ["設置剪力鋼筋可抑制梁端斜拉開裂之發展，並提供破壞之預警", "鋼筋實測降伏強度可遠高於標稱降伏強度，以確保彎矩破壞在剪力破壞後發生", "相較於閉合箍筋，開放式箍筋配置較能提升構材韌性", "箍筋應優先密集配置於撓曲構材之受彎反曲點處，確保結構變形韌性"], "answer": "D"}, {"number": 33, "prompt": "下列鋼結構斜撐構架中，地震時何種耐震性能最差？", "options": ["圖(a)", "圖(b)", "圖(c)", "圖(d)"], "answer": "C"}, {"number": 34, "prompt": "下圖之四條趨勢線中，何者符合薄板（thin-plate）鋼結構構件在受壓力作用下的 Nult/Ny 對 L/r 之關係？ 其中： Nult ：極限承載力 Ny ：降伏載重 L ：構件長度 r ：構件斷面之迴轉半徑 （Radius of Gyration）", "options": ["水平線(A)", "曲線(B)", "曲線(C)", "曲線(D) 圖(a) 圖(b) 圖(c) 圖(d) 代號：80120 頁次：8－8"], "answer": "B"}, {"number": 35, "prompt": "某鋼造構架內有二力桿斜撐，於震後挫屈變形如圖所示，試問其原設計屬何種結構系統？", "options": ["抗彎矩構架（MRF）", "挫屈束制斜撐構架（BRBF）", "同心斜撐構架（CBF）", "偏心斜撐構架（EBF）"], "answer": "D"}, {"number": 36, "prompt": "下列關於結構系統與構件行為之敘述，何者正確？", "options": ["以隔震或消能系統用在建築結構體上，主因是一般的結構系統不耐震", "簡支梁受均布垂直載重與變位的關係中，在載重與斷面形狀不變情況下，梁中點垂直變位 約與跨度的四次方成正比", "H 型鋼梁主要以腹板抵抗彎矩，翼板抵抗剪力", "臺北 101 大樓的頂部巨型圓球作為質量阻尼器，主要目的僅是為了結構耐震"], "answer": "D"}, {"number": 37, "prompt": "於體育館大跨度空間的結構設計中，下列何種結構系統最不符合結構效益？", "options": ["桁架結構系統", "薄殼結構系統", "纜索結構系統", "梁柱結構系統"], "answer": "B"}, {"number": 38, "prompt": "下列關於木材性質之敘述何者錯誤？", "options": ["木材強度性質與纖維方向關係密切", "木材乾燥過程中多少會發生體積變化甚至有乾裂現象", "節、纖維傾斜與起翹變形等都是木材缺點，影響強度", "木材纖維方向受拉強度高且具有韌性"], "answer": "C"}, {"number": 39, "prompt": "木結構作為綠色建築，下列關於其材料性質之敘述何者錯誤？", "options": ["木材有收縮與膨脹現象，主要與含水率有關", "結構用木材可先行鑽孔或加工至預定斷面尺寸後再行乾燥", "強度隨含水率變化", "強度與比重有接近正比的關係"], "answer": "B"}, {"number": 40, "prompt": "臺灣於 2025 年正式開始透過對企業徵收碳費來抑制碳排放量，以符合節能減碳的世界趨勢。 下列那個回收營建廢棄物再利用而製成的建材，不符合「再生綠建材」標準？", "options": ["回收廢棄鋼筋來製作再生鋼材", "回收廢塑膠及廢棄木質傢俱等來製作木塑複合材", "回收營建剩餘土石方製作水硬性混合水泥", "回收廢塑膠、廢玻璃、摻配木質、石質等其他廢棄物，製成再生地磚"], "answer": "D"}], "questionCount": 40, "answerCount": 40}, {"year": "114", "subject": "建築法規", "officialSubject": "營建法規與實務", "durationMinutes": 120, "questions": [{"number": 1, "prompt": "依建築法規定，下列敘述何者錯誤？", "options": ["建築基地，為供建築物本身所占之地面及其所應留設之法定空地", "應留設之法定空地，非依規定不得移轉", "法定空地之留設，應包括建築物與其前後左右之道路或其他建築物間之距離", "法定空地之分割要件及申請核發程序等事項之辦法，由該管直轄市、縣（市）主管建築機關定之"], "answer": "D"}, {"number": 2, "prompt": "依建築法規定，建築物之修建應請領何種執照？", "options": ["修建執照", "建造執照", "雜項執照", "整建執照"], "answer": "B"}, {"number": 3, "prompt": "依建築法規定，公有建築物應由下列何者，將核定或決定之建築計畫、工程圖樣及說明書，向直轄市、 縣（市）（局）主管建築機關請領建築執照？", "options": ["起造機關", "設計人", "承造人", "監造人"], "answer": "A"}, {"number": 4, "prompt": "依建築法規定，經直轄市、縣（市）（局）主管建築機關依法許可或核准後，得不受限制之規定，不包 含下列何者？", "options": ["建築基地與建築線接連部分之最小寬度", "建築物設有騎樓者，其地平面不得與鄰接之騎樓地平面高低不平", "建築物不得突出於建築線之外", "拆除建築物時，應有維護施工及行人安全之設施"], "answer": "D"}, {"number": 5, "prompt": "依建築法規定，直轄市、縣（市）（局）主管建築機關因都市計畫之變更，對已領有執照正在施工中 之建築物，如有妨礙變更後之都市計畫，下列敘述何者正確？", "options": ["得令其依規定辦理變更設計，不得令其停工", "得按原核准圖說施工，但不得再辦理變更設計", "得令其停工，另依規定，辦理變更設計", "起造人依規定必須拆除其建築物之一部或全部時，直轄市、縣（市）（局）政府無需補償之"], "answer": "C"}, {"number": 6, "prompt": "依建築法規定，為維護建築物合法使用與其構造及設備安全，供公眾使用之建築物，應由建築物所有 權人、使用人定期委託中央主管建築機關認可之專業機構或人員檢查簽證，其檢查簽證結果應向下列 何者申報？", "options": ["中央主管建築機關", "中央消防主管機關", "當地主管建築機關", "當地消防主管機關"], "answer": "C"}, {"number": 7, "prompt": "建築師依建築法規定辦理建築物有關公共安全之構造及設備檢查，簽證內容不實者，應處多少新臺幣 罰鍰？", "options": ["3 萬元以上 15 萬元以下", "6 萬元以上 30 萬元以下", "50 萬元以上 250 萬元以下", "100 萬元以上 500 萬元以下"], "answer": "B"}, {"number": 8, "prompt": "依建築法規定，建築法施行前，供公眾使用之建築物而未領有使用執照者，其所有權人應申請核發使 用執照，其使用執照之核發及安全處理，由直轄市、縣（市）政府於下列何者定之？", "options": ["建築技術規則", "土地使用管制規則", "建築管理規則", "建築物變更使用規則"], "answer": "C"}, {"number": 9, "prompt": "依建築基地法定空地分割辦法規定，某建築基地之法定空地併同建築物之分割，分割後建築基地之法 定空地與建築物所占地面連接部分最小寬度，至少幾公尺？", "options": ["1.5", "2", "3", "5 代號：1801 頁次：8－2"], "answer": "B"}, {"number": 10, "prompt": "依建築物室內裝修管理辦法規定，有關室內裝修圖說的署名及簽證，下列敘述何者正確？", "options": ["室內裝修圖說應一律由開業建築師署名負責", "室內裝修圖說應一律由專業設計技術人員（非開業建築師）署名負責", "室內裝修設計內容涉及建築物之分間牆位置變更、增加或減少經審查機構認定涉及公共安全時，應 一律經開業建築師簽證負責", "室內裝修設計內容涉及建築物之分間牆位置變更、增加或減少經審查機構認定涉及公共安全時，應 一律經專業設計技術人員（非開業建築師）簽證負責"], "answer": "C"}, {"number": 11, "prompt": "依招牌廣告及樹立廣告管理辦法規定，下列何者非屬適用範圍？", "options": ["固著於建築物牆面上之電腦顯示板", "以繩索繫綁於建築物牆面上之帆布廣告", "樹立於地面之牌樓", "設置於屋頂之廣告塔"], "answer": "B"}, {"number": 12, "prompt": "依建築物使用類組及變更使用辦法規定，有關變更使用執照相關期限，下列敘述何者錯誤？", "options": ["建築物申請變更使用經主管建築機關審查合格後，其須施工者，發給同意變更文件時應核定施工期 限，最長不得超過 2 年", "申請人因故未能於施工期限內施工完竣時，得於期限屆滿前申請展期 6 個月，並以 1 次為限", "未依規定申請展期或已逾展期期限仍未完工者，其同意變更文件自規定得展期之期限屆滿之日起， 失其效力", "建築物申請變更使用須增設停車空間於鄰地空地時，其鄰地所有權人不得出具附有期限之土地使用 權同意書"], "answer": "B"}, {"number": 13, "prompt": "依建築法規定，建築工程部分完竣後可供獨立使用者，得核發部分使用執照。再依建築物部分使用執 照核發辦法規定，所稱建築工程部分完竣及幢棟定義，下列敘述何者錯誤？", "options": ["基地內有二幢以上建築物，其中任一幢業經全部施工完竣，該幢得經申請後核發部分使用執照", "幢的判斷，必須建築物整體結構體獨立不與其他建築物相連，且其使用機能可獨立分開者", "基地內有連棟式建築物，其中任一棟業經施工完竣，該棟得經申請後核發部分使用執照", "棟的判斷，必須以一單獨或共同出入口及以無開口之防火牆及防火樓板所區劃分開者"], "answer": "C"}, {"number": 14, "prompt": "依原有合法建築物公共安全改善辦法規定，各類組建築物各改善項目的改善方式，與下列何者無關？", "options": ["建築物領得建造執照時間", "建築物興建完成時間", "建築物產權移轉時間", "建築物領得變更使用執照時間"], "answer": "A"}, {"number": 15, "prompt": "依山坡地建築管理辦法規定，有關從事山坡地建築，下列敘述何者錯誤？", "options": ["本辦法所稱山坡地係指直轄市、縣（市）政府依山坡地保育利用條例第 3 條規定劃定，報請當地都 市計畫委員會核定公告之公、私有土地", "從事山坡地建築，原則上應分申請雜項執照及申請建造執照兩階段辦理", "經直轄市、縣（市）政府認定雜項工程必需與建築物一併施工者，其雜項執照得併同於建造執照中 申請之", "雜項工程進行時，應施作適足之安全防護措施"], "answer": "B"}, {"number": 16, "prompt": "下列何者非建築物公共安全檢查簽證及申報辦法規定 H-2 組集合住宅防火避難設施及設備安全標準 檢查之簽證項目？", "options": ["直通樓梯", "內部裝修材料", "昇降設備", "緊急供電系統"], "answer": "C"}, {"number": 17, "prompt": "依建築物公共安全檢查簽證及申報辦法規定，專業機構指派所屬檢查員辦理耐震能力評估檢查作業， 下列敘述何者錯誤？", "options": ["經初步評估判定結果為尚無疑慮者，得免進行詳細評估", "經初步評估判定結果為有疑慮者，應辦理詳細評估", "經初步評估判定結果為有疑慮，經申報人檢具投保公共意外責任保險證明者，得免進行詳細評估", "經初步評估判定結果為確有疑慮，且未逕行辦理補強或拆除者，應辦理詳細評估"], "answer": "C"}, {"number": 18, "prompt": "依建築師法規定，開業建築師得兼任或兼營下列何種職業？", "options": ["建築材料商", "依公務人員任用法任用之公務人員", "不動產營業員", "營造業之主任技師 代號：1801 頁次：8－3"], "answer": "D"}, {"number": 19, "prompt": "依建築師法規定，下列敘述何者錯誤？", "options": ["建築師受委託辦理建築物之設計者，應負該工程設計之責任", "建築師受委託辦理建築物之監造者，應負監督該工程施工之責任", "有關建築物結構與設備等專業工程部分，除 5 層以下非供公眾使用之建築物外，應由承辦建築師交 由依法登記開業之專業技師負責辦理，建築師並負連帶責任。當地無專業技師者，不在此限", "建築師受委託辦理建築物之施工者，應負工程品質查核之責任"], "answer": "B"}, {"number": 20, "prompt": "開業建築師有違反建築師法相關規定時應接受之懲戒處分，不包括下列何者？", "options": ["警告、申誡", "記過", "停止執行業務 2 月以上 2 年以下", "撤銷或廢止開業證書"], "answer": "B"}, {"number": 21, "prompt": "建築技術規則所稱建築物高度，指自基地地面計量至建築物最高部分之垂直高度，但部分項目得免計 入。有關不計入建築物高度之項目，下列敘述何者錯誤？", "options": ["女兒牆高度 1.5 公尺", "水箱、水塔設於屋頂突出物上高度合計 9 公尺", "非平屋頂之屋頂斜率三分之一", "突出屋面 4.5 公尺的再生能源節能設施"], "answer": "D"}, {"number": 22, "prompt": "依建築技術規則規定，建築物之居室應設置採光用窗或開口，其採光面積或有效採光面積規定，下列 何者錯誤？", "options": ["養老院之居室不得小於樓地板面積八分之一", "學校教室不得小於樓地板面積五分之一", "用天窗採光者，有效採光面積按其採光面積之 3 倍計算", "位於地板面以上 85 公分範圍內之窗或開口面積均不得計入採光面積之內"], "answer": "C"}, {"number": 23, "prompt": "依建築技術規則規定，下列何者不屬於應為防火構造建築物之範圍？", "options": ["建築物為 1 層樓，總樓地板面積為 1500 平方公尺的倉庫", "建築物為 3 層樓的社區活動中心", "建築物為 2 層樓，總樓地板面積為 250 平方公尺的住宅", "建築物為 4 層樓，總樓地板面積為 3000 平方公尺的百貨商場"], "answer": "A"}, {"number": 24, "prompt": "依建築技術規則有關排煙設備構造之規定，下列敘述何者錯誤？", "options": ["防煙壁每一區劃面積得為 1500 平方公尺", "區劃範圍任一部分至排煙口水平距離不得超過 45 公尺", "排煙口之開口面積不得小於防煙區劃部分樓地板面積之 2%", "排煙口可以開設在天花板"], "answer": "A"}, {"number": 25, "prompt": "依建築技術規則有關建築物於避難層開向屋外出入口之規定，下列何者錯誤？", "options": ["A-1 類組建築物每處入口寬度及高度均不得小於 1.8 公尺", "A-1 類組建築物在避難層供公眾使用之出入口應為外開門", "直通樓梯在避難層之出入口直接開向道路，免設 2 處以上不同方向之出入口", "直通樓梯於避難層開向屋外之出入口寬度不得小於 1.2 公尺"], "answer": "B"}, {"number": 26, "prompt": "依建築技術規則規定，供車庫使用之特定建築物，利用汽車昇降機設備者，應按車庫樓地板面積至多 每多少平方公尺以內為一單位裝置昇降機一台？", "options": ["1000", "1200", "1500", "2000"], "answer": "D"}, {"number": 27, "prompt": "依建築技術規則有關基地內通路之規定，下列敘述何者錯誤？", "options": ["以基地內通路為進出道路之建築物，其總樓地板面積合計在 1000 平方公尺以上者，通路寬度為 6 公尺", "基地內各棟建築物間及建築物至建築線間之通路，得計入法定空地面積", "基地內通路之長度在 10 公尺以上未滿 20 公尺者，其寬度為 3 公尺", "基地內通路為連通建築線者，得穿越同一基地建築物之地面層，穿越之深度不得超過 12 公尺"], "answer": "B"}, {"number": 28, "prompt": "依建築技術規則規定，供學校使用之建築物，按其主管機關核定計畫容納使用人數至少每人多少平方 公尺計算，整體規劃附建防空避難設備？", "options": ["0.5", "0.75", "0.85", "1.0"], "answer": "B"}, {"number": 29, "prompt": "依建築技術規則規定，煙囪之高度至少超過多少公尺，應為鋼筋混凝土造或鋼鐵造？", "options": ["6", "10", "12", "15 代號：1801 頁次：8－4"], "answer": "A"}, {"number": 30, "prompt": "依建築技術規則規定，挖土深度至少多少公尺以上者，除地質良好，不致發生崩塌或其周圍狀況無安 全之慮者外，應有適當之擋土設備？", "options": ["1.5", "2.0", "2.5", "3.0"], "answer": "B"}, {"number": 2, "prompt": "公尺；其梯廳面積至多未超過該層樓地板面積百分之多少，得不計入該層樓地板面積？", "options": ["5", "10", "12.5", "15"], "answer": "B"}, {"number": 32, "prompt": "依建築技術規則，有關無障礙設施之規定，下列敘述何者錯誤？", "options": ["建築物依相關法令規定免裝設衛生設備者，除使用類組為 H-2 組住宅或集合住宅外，仍應於每戶內 設置至少 1 處無障礙廁所盥洗室", "建築物依實際使用需要設有共用浴室者，應於每幢建築物內至少設置 1 處無障礙浴室", "建築物依實際使用需要設有固定觀眾席位者，應於該場所內至少設置 1 處輪椅觀眾席位", "建築物依相關法令規定應設置停車空間者，應於該場所內至少設置 1 輛無障礙停車位"], "answer": "C"}, {"number": 33, "prompt": "依建築技術規則規定，高層建築物設有燃氣設備時，應將燃氣設備集中設置，並設置瓦斯漏氣自動警 報設備，且與其他部分應以至少多少小時以上防火時效之牆壁、防火門窗等防火設備及該層防火構造 之樓地板予以區劃分隔？", "options": ["0.5", "1", "2", "3"], "answer": "B"}, {"number": 34, "prompt": "依建築技術規則規定，山坡地基地需繪製實測地形圖計算平均坡度，其圖面比例尺至少不得小於多少？", "options": ["1/500", "1/1000", "1/1200", "1/1500"], "answer": "B"}, {"number": 35, "prompt": "依建築技術規則規定，工廠建築之廠房附屬空間設置面積應符合相關規定，下列何者正確？", "options": ["辦公室（含守衛室、接待室及會議室）及研究室之合計面積不得超過作業廠房面積四分之一", "作業廠房面積在 300 平方公尺以上之工廠，得附設單身員工宿舍，其合計面積不得超過作業廠房面 積三分之一", "員工餐廳（含廚房）及其他相關勞工福利設施之合計面積不得超過作業廠房面積五分之一", "附屬空間合計樓地板面積不得超過總樓地板面積之五分之二"], "answer": "C"}, {"number": 36, "prompt": "依建築技術規則規定，除都市計畫書圖或都市計畫法規另有規定外，實施都市計畫地區建築基地綜合 設計之開放空間，下列敘述何者錯誤？", "options": ["指建築基地內依規定留設達一定規模且連通道路開放供公眾通行或休憩之開放空間", "廣場式開放空間任一邊之最小淨寬度應在 6 公尺以上，且不得設置頂蓋", "廣場式開放空間留設之最小面積，於住宅區、文教區、風景區或機關用地為 200 平方公尺以上，或 於商業區或市場用地為 100 平方公尺以上", "基地內供車輛出入之車道部分，不計入開放空間"], "answer": "B"}, {"number": 37, "prompt": "依建築技術規則規定，建築物室內裝修材料、樓地板面材料及窗，其綠建材使用率最少應達總面積百 分之多少以上，但窗未使用綠建材者，得不計入總面積檢討？", "options": ["30", "45", "60", "75"], "answer": "D"}, {"number": 38, "prompt": "依建築技術規則規定，有關建築耐風設計，除依建築物耐風設計規範及解說規定外，下列敘述何者錯誤？", "options": ["各種地況下，風速呈現隨距地面高度增加而遞增之垂直分布", "任一地點之基本設計風速，係假設該地點之地況為平坦開闊之地面，離地面 5 公尺高，相對於 50 年回歸期之 10 分鐘平均風速", "一般建築物之設計風速，其回歸期為 50 年，其他各類建築物應依其重要性，對應合宜之回歸期， 訂定用途係數", "對風較敏感之柔性建築物，其陣風反應因子應考慮建築物之動力特性"], "answer": "B"}, {"number": 39, "prompt": "依建築技術規則規定，下列有關電氣設備之敘述，何者錯誤？", "options": ["電氣設備配電場所應設置於地面或地面以上樓層。如有困難必須設置於地下樓層時，僅能設於地下 一層", "配電場所設置於地下層者，應裝設必要之防水或擋水設施。但地面層之開口均位於當地洪水位以上 者，不在此限", "電氣設備之管道間應有足夠之空間容納各電氣系統管線。其與電信、給水排水、消防、燃燒、空氣 調節及通風等設備之管道間採合併設置時，電氣管道與給水排水管、消防水管、燃氣設備之供氣管 路、空氣調節用水管等管道應予以分隔", "緊急電源之供應採用蓄電池設備者，蓄電池室應有適當之進氣裝置 代號：1801 頁次：8－5"], "answer": "C"}, {"number": 40, "prompt": "依建築技術規則地下建築物之規定，供地下使用單元使用之總樓地板面積為 3500 平方公尺時，最多 應按每多少平方公尺，以具有 1 小時以上防火時效之牆壁、防火門窗等防火設備及該處防火構造之樓 地板予以區劃分隔？", "options": ["500", "1000", "2000", "3000"], "answer": "C"}, {"number": 41, "prompt": "下列何者非屬都市計畫法所規定的都市計畫變更回饋項目？", "options": ["公共設施用地", "可建築土地或樓地板面積", "協助社工教育訓練", "一定金額"], "answer": "A"}, {"number": 42, "prompt": "依都市計畫法規定，土地重劃之範圍選定後，直轄市、縣（市）政府得公告禁止該地區之土地移轉、 分割、設定負擔、新建、增建、改建及採取土石或變更地形。其禁止期間，最長不得超過多久？", "options": ["6 個月", "1 年", "1 年 6 個月", "2 年"], "answer": "C"}, {"number": 43, "prompt": "依都市計畫定期通盤檢討實施辦法規定，下列敘述何者錯誤？", "options": ["都市計畫發布實施已屆滿計畫年限或 20 年者，應予全面通盤檢討", "都市計畫通盤檢討時，相鄰接之都市計畫，得合併辦理之", "辦理細部計畫通盤檢討時，其涉及主要計畫部分，得一併檢討之", "辦理主要計畫或細部計畫全面通盤檢討時，應參考機關、團體或人民建議作必要之修正"], "answer": "B"}, {"number": 44, "prompt": "依都市更新條例規定，下列何者非地方政府優先劃定都市更新地區之考量因素？", "options": ["建築物年代久遠有傾頹或朽壞之虞", "建築物未符合都市應有之機能", "建築物基準容積過低", "建築物排列不良足以妨害公共安全"], "answer": "C"}, {"number": 45, "prompt": "依都市計畫法臺灣省施行細則規定，下列何者屬違規使用？", "options": ["住宅區內一樓設置便利商店", "行政區內作住宅使用", "風景區內作住宅使用", "文教區內設置博物館"], "answer": "C"}, {"number": 46, "prompt": "依都市更新條例規定，至少逾多少人之土地及合法建築物所有權人自行實施都市更新事業時，應組織 都市更新會？", "options": ["5", "6", "7", "8"], "answer": "B"}, {"number": 47, "prompt": "依都市更新條例規定，為鼓勵民眾參與都市更新，更新後地價稅及房屋稅減半徵收多久？", "options": ["半年", "1 年", "2 年", "3 年"], "answer": "C"}, {"number": 48, "prompt": "依都市更新條例施行細則規定，都市更新事業計畫表明之重建區段之土地使用計畫，含建築物配置及 設計圖說，其比例尺最小不得小於多少？", "options": ["1/100", "1/500", "1/1000", "1/1200"], "answer": "B"}, {"number": 49, "prompt": "依國土計畫法與區域計畫法之規定，下列敘述何者正確？", "options": ["全國國土計畫公告實施之日起，區域計畫法不再適用", "直轄市、縣（市）國土計畫公告實施之日起，區域計畫法不再適用", "全國國土計畫由中央主管機關擬訂、審議，報請行政院核定", "直轄市主管機關擬定之區域計畫，應經直轄市區域計畫委員會審議通過，報請行政院核定"], "answer": "C"}, {"number": 50, "prompt": "依國土計畫法規定，國土計畫核定、公告實施及復議，下列敘述何者錯誤？", "options": ["國土計畫經核定後，擬訂機關應於接到核定公文之日起 30 日內公告實施", "國土計畫公告實施應將計畫函送各有關直轄市、縣（市）政府及鄉（鎮、市、區）公所分別公開展 覽；其展覽期間，不得少於 60 日；計畫內容重點應登載於政府公報、新聞紙，並以網際網路或其 他適當方法廣泛周知", "直轄市、縣（市）國土計畫未依規定公告者，中央主管機關得逕為公告及公開展覽", "直轄市、縣（市）國土計畫擬訂機關對於核定之國土計畫申請復議時，應於公告實施前提出，並以"], "answer": "D"}, {"number": 51, "prompt": "依國土計畫法施行細則規定，直轄市、縣（市）國土計畫年期以不超過多少年為原則？", "options": ["30 年", "25 年", "20 年", "10 年"], "answer": "D"}, {"number": 52, "prompt": "依區域計畫法之規定，下列何者不是區域計畫應表明事項？", "options": ["人口及經濟成長、土地使用、運輸需要、資源開發等預測", "自然資源之開發及保育", "土地分區使用計畫及土地分區管制", "老樹保存計畫 代號：1801 頁次：8－6"], "answer": "C"}, {"number": 53, "prompt": "依非都市土地使用管制規則規定，關於非都市土地建蔽率及容積率，下列敘述何者正確？", "options": ["丁種建築用地之建蔽率為 60%，容積率為 300%", "工商綜合區用地之建蔽率及容積率與丙種建築用地相同", "丙種建築用地之建蔽率為 40%，容積率為 160%", "直轄市或縣市政府得視實際需要酌予調降非都市土地建蔽率及容積率，並報請中央主管機關備查"], "answer": "B"}, {"number": 54, "prompt": "依原有合法建築物公共安全改善辦法規定，有關防火區劃之防火門窗改善內容，下列敘述何者錯誤？", "options": ["常時關閉式之防火門應免用鑰匙即可開啟，並裝設開啟後自行關閉之裝置", "常時關閉式之防火門其門扇或門樘上應標示常時關閉式防火門等文字", "常時開放式之防火門應裝設利用煙感應器連動或於火災發生時能維持開啟之裝置", "常時開放式之防火門其關閉後應免用鑰匙即可開啟，且開啟後自行關閉"], "answer": "C"}, {"number": 55, "prompt": "依國家公園法規定，下列何種行為須經國家公園管理處許可，方可為之？", "options": ["焚燬草木或引火整地", "放牧牲畜", "於樹木、岩石及標示牌加刻文字或圖形", "任意拋棄果皮、紙屑或其他污物"], "answer": "B"}, {"number": 56, "prompt": "依非都市土地開發審議作業規範規定，申請非都市土地開發，於基地內劃設必要之保育區，保育區面 積至少應有多少比率維持原始之地形地貌，不得開發？", "options": ["50%", "60%", "70%", "80%"], "answer": "C"}, {"number": 57, "prompt": "依公寓大廈管理條例規定，新建建築物之起造人應於何種時機及方式提列公共基金？", "options": ["於建造執照申請時，向地方主管機關公庫繳納", "於使用執照申請時，向地方主管機關公庫繳納", "於管理組織成立並向地方主管機關完成報備後，向地方主管機關公庫繳納", "於管理組織成立並向地方主管機關完成報備後，直接撥付管理組織之公共基金帳戶"], "answer": "D"}, {"number": 58, "prompt": "某通信業務經營者擬租用其公司登記地之公寓大廈屋頂平臺裝置行動通信網路業務基地臺，在規約無 限制條件之情形下，依公寓大廈管理條例，仍須符合什麼要件？", "options": ["須經管理委員會同意", "須經區分所有權人會議決議", "須經區分所有權人會議決議及頂層區分所有權人同意", "須經四分之三以上區分所有權人之同意"], "answer": "B"}, {"number": 59, "prompt": "依公寓大廈管理條例，有關公寓大廈管理維護公司之相關規定，下列敘述何者錯誤？", "options": ["資本額應在新臺幣 1000 萬元以上", "應置有事務管理人員 4 人以上，及技術服務人員 4 人以上", "公寓大廈管理維護公司之公司名稱中應標示「公寓大廈管理維護」字樣", "管理維護公司登記證有效期限為 4 年，期限屆滿前，應向中央主管機關申請換發登記證"], "answer": "D"}, {"number": 60, "prompt": "依公寓大廈管理條例規定，某建設公司刻正推動都市更新案件，其都市更新事業計畫業經當地主管機 關核准，但未經領得何種文件前，不得辦理銷售？", "options": ["拆除執照", "建造執照", "使用執照", "權利變換計畫"], "answer": "C"}, {"number": 61, "prompt": "依營造業法規定，營造業的分類及許可，下列敘述何者正確？", "options": ["綜合營造業分為甲、乙、丙及丁四等", "營造業分綜合營造業、專業營造業及建築設計業", "土木包工業應於原登記直轄市、縣（市）地區營業，不得越區營業", "專業營造業應置符合各專業工程項目規定之專任工程人員"], "answer": "C"}, {"number": 62, "prompt": "依營造業法規定，綜合營造業承攬之營繕工程或專業工程項目，交由專業營造業承攬，其轉交工程相 關規定，下列敘述何者錯誤？", "options": ["施工責任由原承攬之綜合營造業負責", "受轉交之專業營造業就轉交部分，負連帶責任", "受轉交之專業營造業，不論任何情況，民法之抵押權及因添附而生之請求權，均不及於綜合營造業 對於定作人之價金或報酬請求權", "綜合營造業承攬之營繕工程或專業工程項目，與定作人約定需自行施工者，應自行施工 代號：1801 頁次：8－7"], "answer": "B"}, {"number": 63, "prompt": "依營造業法施行細則規定，某營造廠欲承攬下列何種規模之工程，應置工地主任？", "options": ["承攬金額新臺幣 4000 萬元之工程", "建築物高度 32 公尺之工程", "建築物地下室開挖 12 公尺之工程", "橋樑柱跨距 20 公尺之工程"], "answer": "C"}, {"number": 64, "prompt": "依營造業法相關法規規定，有關營造業承攬之敘述，下列何者錯誤？", "options": ["營造業聯合承攬工程時，其承攬金額按契約之各營造業聯合承攬協議書所載出資比例分別計算", "營造業承攬工程契約約定之工作項目非屬營造業營業範圍者，由定作人出具金額證明，仍應全數計 入承攬總額", "甲等綜合營造業承攬造價限額為其資本額之 10 倍", "乙等綜合營造業承攬造價限額為新臺幣 9000 萬元"], "answer": "D"}, {"number": 65, "prompt": "下列何種採購須依政府採購法之規定辦理？", "options": ["民間辦理供公眾使用建築之採購", "法人接受機關補助辦理之採購，未達公告金額者", "公營事業辦理之採購", "法人或團體接受機關補助辦理藝文採購"], "answer": "C"}, {"number": 66, "prompt": "依政府採購法規定，有關履約管理，下列敘述何者正確？", "options": ["分包廠商須就得標廠商契約之全部，與得標廠商連帶負瑕疵擔保責任", "得標廠商違反規定轉包其他廠商時，僅得要求損害賠償，不得解除契約、終止契約或沒收保證金", "分包，指將原契約中應自行履行之全部或其主要部分，由其他廠商代為履行", "得標廠商應自行履行契約，不得轉包"], "answer": "D"}, {"number": 67, "prompt": "依政府採購法規定，廠商因查驗或驗收不合格，情節重大者，除經判決撤銷原處分或上級機關核准外， 第 3 次被刊登於政府採購公報，應自刊登之次日起至少多少期間內不得參加投標或作為決標對象或分 包廠商？", "options": ["6 個月", "10 個月", "1 年", "2 年"], "answer": "A"}, {"number": 68, "prompt": "依政府採購法相關規定，技術服務履約期間，下列何者非屬機關應調整增加契約價金予技術服務廠商 之事項？", "options": ["於設計核准後須辦理機關需求變更者", "非技術服務廠商之因素超出技術服務契約或工程契約規定施工期限所需增加之監造及相關費用", "超過契約內容之設計報告製圖、送審、審圖等相關費用", "設計錯誤修正書圖之相關費用"], "answer": "B"}, {"number": 69, "prompt": "依建築物無障礙設施設計規範規定，有關無障礙坡道，下列敘述何者錯誤？", "options": ["未設樓梯，以坡道取代樓梯者，坡道淨寬最小為 120 公分", "高差超過 20 公分之坡道，坡度不得大於 1/12", "高差超過 5 公分未達 20 公分者，坡度不得大於 1/10", "高差超過 3 公分未達 5 公分者，坡度不得大於 1/5"], "answer": "B"}, {"number": 70, "prompt": "依建築技術規則規定，為便利行動不便者進出及使用建築物，新建或增建建築物，應依規定設置無障 礙設施，下列敘述何者正確？", "options": ["獨棟或連棟建築物，該棟自地面層至最上層屬 2 戶以上之不同單位且第 2 層以上僅供住宅使用者， 不在此限", "供住宅使用之公寓大廈專有及約定專用部分，不在此限", "除公共建築物外，建築基地面積未達 300 平方公尺或每棟每層樓地板面積均未達 150 平方公尺，不 在此限", "建築物因建築基地地形、垂直增建、構造或使用用途特殊，設置無障礙設施確有困難，經中央主管 建築機關核准者，得不適用無障礙建築物專章一部或全部之規定"], "answer": "A"}, {"number": 71, "prompt": "依建築物無障礙設施設計規範規定，樓梯上所有梯級之級高及級深應統一，級高（R）應為 16 公分以 下，級深（T）應為 26 公分以上，且應符合下列何者規定？", "options": ["55 公分≦2 R + T≦70 公分", "55 公分≦2 R + T≦65 公分", "50 公分≦2 R + T≦60 公分", "50 公分≦2 R + T≦55 公分 代號：1801 頁次：8－8"], "answer": "C"}, {"number": 72, "prompt": "依建築物無障礙設施設計規範有關無障礙浴室設置浴缸規定，下列敘述何者錯誤？", "options": ["浴缸內側長度不得大於 135 公分，浴缸外側距地板面高度 50 公分至 55 公分", "浴缸側向牆壁應設置水平扶手及垂直扶手", "出水側對向牆壁應設置垂直扶手，出水側未有對向牆壁者，扶手應設置於出水側側邊", "無障礙浴室內設置於浴缸時應設置 2 處求助鈴"], "answer": "A"}, {"number": 73, "prompt": "依建築物無障礙設施設計規範規定，機車停車位之出入口寬度及通達無障礙機車停車位之車道寬度至 少均不得小於多少公分？", "options": ["120", "150", "180", "210"], "answer": "A"}, {"number": 74, "prompt": "下列何項法規之修正，應經立法院通過，總統公布？", "options": ["公寓大廈管理條例", "建築技術規則", "農業用地興建農舍辦法", "營造業法施行細則"], "answer": "B"}, {"number": 75, "prompt": "下列何者非住宅法規定主管機關新建社會住宅之方式？", "options": ["將公有土地按當期土地公告現值讓售予民間興建", "以公有土地或建築物參與都市更新分回建築物及其基地", "合建分屋", "直接興建"], "answer": "A"}, {"number": 76, "prompt": "依建築物無障礙設施設計規範有關無障礙昇降設備規定，下列敘述何者錯誤？", "options": ["昇降機出入口處之地板面，應與機廂地板面保持平整，其與機廂地板面之水平間隙不得大於 3.2 公分", "除建築物使用類組為 H-2 組住宅、集合住宅外，昇降機門淨寬不得小於 90 公分，機廂深度不得小 於 125 公分（不需扣除扶手占用之空間）", "機廂內扶手上緣距機廂地面應為 75 公分", "機廂內應設置語音系統以報知樓層、行進方向及開關情形"], "answer": "C"}, {"number": 77, "prompt": "依文化資產保存法規定，若建造物經列為暫定古蹟，致權利人之財產受有損失，主管機關應給與合理 補償，其補償金額如何計價？", "options": ["由主管機關與古蹟權利人協議定之", "按建築物之評定標準價格及當期土地公告現值之和", "委由全國不動產估價師公會進行查估", "提報文化資產審議委員會審議"], "answer": "A"}, {"number": 78, "prompt": "依都市危險及老舊建築物加速重建條例規定，如某基地符合本條例之合法建築物基地面積為 1200 平 方公尺，並合併鄰接之土地面積 1500 平方公尺辦理重建，其適用本條例建築容積獎勵規定之土地面 積至多不得超過多少平方公尺？", "options": ["1200", "1500", "2200", "2700"], "answer": "A"}, {"number": 79, "prompt": "依文化資產保存法規定，下列敘述何者錯誤？", "options": ["古蹟、歷史建築之中央主管機關為文化部；自然地景之中央主管機關為環境部", "主管機關得就古蹟保存計畫內容，依區域計畫法、都市計畫法或國家公園法等有關規定，編定、劃 定或變更為古蹟保存用地或保存區、其他使用用地或分區", "自然地景、自然紀念物係指具保育自然價值之自然區域、特殊地形、地質現象、珍貴稀有植物及礦 物之有形文化資產", "自然地景、自然紀念物依其主管機關，區分為國定、直轄市定、縣（市）定 3 類"], "answer": "D"}, {"number": 80, "prompt": "在非離島地區申請興建個別農舍，下列敘述何者不符農業用地興建農舍辦法之規定？", "options": ["興建之農舍，得免設置建築物污水處理設施", "農舍興建圍牆，不得超過農舍用地面積範圍", "地下層每層興建面積，不得超過農舍建築面積", "農舍之放流水應符合放流水標準，並排入排水溝渠"], "answer": "B"}], "questionCount": 80, "answerCount": 80}, {"year": "114", "subject": "建築結構", "officialSubject": "建築結構", "durationMinutes": 120, "questions": [{"number": 1, "prompt": "下列何者為材料彈性模數 E（modulus of elasticity）之單位？", "options": ["N", "kgf/cm", "kgf/cm3", "MPa"], "answer": "D"}, {"number": 2, "prompt": "下列有關混凝土性質的敘述，何者錯誤？", "options": ["抗拉強度約為抗壓強度的 10%", "規範保守以壓應變 0.003 視為壓碎破壞", "常重混凝土的彈性模數 cE 和 cf  的平方根成正比", "單位水泥量較少的混凝土，水化作用產生之水化熱較多"], "answer": "D"}, {"number": 3, "prompt": "如圖所示，x 軸為作用力的反覆加載週期數目（N），y 軸為鋼所承受的應力（MPa）大小，若 所承受的應力比材料本身的降伏應力小，該圖主要在說明鋼的何種性質？", "options": ["疲勞現象", "彈性係數", "彈塑性行為", "韌性"], "answer": "A"}, {"number": 4, "prompt": "一長度為 2 m 圓棒，直徑為 30 mm，彈性模數為 70 GPa，波松比（Poisson's ratio）0.3，當其 受到 100 kN 拉力時，下列敘述何者正確？", "options": ["軸向應力為 120 MPa", "伸長量為 2 mm", "軸向勁度為 20 kN/mm", "直徑減少量為 0.018 mm"], "answer": "D"}, {"number": 5, "prompt": "關於圓球薄殼結構，下列敘述何者錯誤？", "options": ["圓頂重量過大時，會造成圓頂底部向外變形過大而開裂，此時必須加設鋼箍作為壓力環", "在對稱自重作用下，經度纖維均受壓應力", "在對稱自重作用下，天頂角大於 52°範圍，緯度纖維均受張應力", "為不可展開薄殼"], "answer": "A"}, {"number": 6, "prompt": "關於薄膜結構，下列敘述何者正確？", "options": ["薄膜僅能受壓應力", "薄膜元素會有彎曲應力", "薄膜構造通常伴隨拉索是為維持其薄膜張力", "薄膜不會有應力集中現象"], "answer": "C"}, {"number": 7, "prompt": "下列何種結構系統較不適用於超過 50 公尺之高層建築？", "options": ["剛構架與斜撐構架系統", "拱結構系統", "管狀（tube）結構系統", "巨型構架（mega-frame）系統"], "answer": "B"}, {"number": 8, "prompt": "有關高層建築結構系統與設計，下列敘述何者錯誤？①高層建築於設計風力下之層間位移角， 不得大於 2 % ②高層建築若採用外伸穩定架（outrigger）搭配帶狀桁架系統，應儘量配置於 建築底層以抑制垂直變形 ③某棟建築高度 52 公尺且樓層數 16 層，其平立面規則，故耐震 設計可採靜力分析", "options": ["僅①②", "僅②③", "僅①③", "①②③"], "answer": "D"}, {"number": 9, "prompt": "某等跨距構架活載重 w 全部負載、間隔負載如圖(a)、圖(b)所示，若活載重大於靜載重，下列 敘述何者正確？（彎矩圖繪製於斷面受拉側）", "options": ["(a)、(b)對應之彎矩圖分別為(d)、(c)，中間跨梁中央上、下部均需留設拉力鋼筋", "(a)、(b)對應之彎矩圖分別為(c)、(d)，中間跨梁中央下部需留設拉力鋼筋", "(a)、(b)對應之彎矩圖分別為(d)、(c)，中間跨梁中央上部需留設拉力鋼筋", "(a)、(b)對應之彎矩圖分別為(c)、(d)，中間跨梁中央上、下部均需留設拉力鋼筋 鋼 反覆加載週期數目（N） 應力（MPa） (a) (b) (c) (d) W W W 代號：80120 頁次：8－3"], "answer": "A"}, {"number": 10, "prompt": "若一地震之顯著振動週期為 1 秒，則對一般建築物而言，樓高幾層者易與該地震形成共振現象？", "options": ["5 層", "10 層", "30 層", "50 層"], "answer": "B"}, {"number": 11, "prompt": "高層建築物可利用於較高樓層處懸吊鋼球或設置水箱來抵抗風力作用，則下列敘述何者 錯誤？", "options": ["高樓層處懸吊鋼球或設置水箱來抵抗風力屬於被動控制", "高樓層處懸吊鋼球或設置水箱來抵抗風力可以減少建築物擺動幅度", "採用懸吊鋼球時，鋼球應能自由擺動", "採用密閉式水箱時，內部充滿水之抗風效果較佳"], "answer": "D"}, {"number": 12, "prompt": "如圖所示之甲乙兩支梁承受相同垂直均布靜載重，若兩梁皆為鋼筋混凝土構造，斷面(1)、(2) 皆鄰近梁端點。依圖示載重配置主要拉力鋼筋位置時，下列敘述何者正確？", "options": ["斷面(1)於甲梁配在梁頂面，乙梁配在梁底面", "斷面(2)於甲梁配在梁底面，乙梁配在梁頂面", "斷面(1)於甲、乙梁皆配在梁頂面", "斷面(2)於甲、乙梁皆配在梁底面"], "answer": "C"}, {"number": 13, "prompt": "下列有關結構穩定性與靜定性之敘述，何者錯誤？", "options": ["靜定結構必為穩定結構", "若支承之反力共線、平行或交於一點，稱為外在幾何的不穩定", "若結構物之反力超過三個以上，則該結構一定是靜不定結構", "若一結構物為靜不定結構且為韌性結構，則該結構物具有應力重新分配的能力"], "answer": "D"}, {"number": 14, "prompt": "圖示之梁構造中 C 為鉸接，不考慮自重影響，在 B 出現微小垂直沉陷時，下列敘述何者 正確？", "options": ["本結構為二次靜不定", "AB、CD 均有內力", "AB、CD 均無內力", "AB 有內力，CD 無內力"], "answer": "B"}, {"number": 15, "prompt": "如圖所示的桁架，C 點承受一個集中載重 P 之作用，假設每一支桿件的彈性模數和斷面尺寸 均相同，下列敘述何者錯誤？", "options": ["此桁架為靜定且穩定桁架", "此桁架受溫度變化後，會產生軸向應力", "此桁架受溫度變化後，會產生軸向應變", "可應用單位虛載重法分析此桁架 C 點之垂直變位△C"], "answer": "A"}, {"number": 16, "prompt": "圖中所示一正三角形桁架，求可施加之最大負載 P，使得無任何桿件受力超過 3 kN 之張力或 2.5 kN 之壓力？", "options": ["4.3", "6.3", "8.3", "10.3"], "answer": "A"}, {"number": 17, "prompt": "圖中桁架結構有幾支零桿？", "options": ["5", "4", "3", "2"], "answer": "B"}, {"number": 18, "prompt": "如圖所示桁架結構，桿件 EJ 之軸力為多少 kN？", "options": ["5", "10", "12", "15"], "answer": "C"}, {"number": 19, "prompt": "圖示 B 點受力的桁架結構，下列構件內力與支承反力的大小與方向的敘述何者正確？", "options": ["FAB 450 N（拉）", "FBC 1000 N（拉）", "FAC 800 N（壓）", "Ay300 N（向上）"], "answer": "D"}, {"number": 20, "prompt": "圖示桁架 A、I 點為鉸支承，在 D 點受向下 4 kN 荷重，下列關於構件內力與方向的敘述何者 錯誤？", "options": ["HB 桿 4 kN（拉）", "CE 桿 4.8 kN（壓）", "AB 桿 5.3 kN（壓）", "HG 桿 4.8 kN（拉）"], "answer": "D"}, {"number": 21, "prompt": "下圖桁架結構中 C、D 為鉸支承，BC 桿之受力狀況，下列何者正確（T 為張力，C 為壓力）？", "options": ["FBC 2.25 kN（T）", "FBC 4 kN（C）", "FBC 6.75 kN（C）", "FBC 9.25 kN（T）"], "answer": "D"}, {"number": 22, "prompt": "桁架結構如下圖，a~d 桿件中何者軸拉力最大？", "options": ["a 桿件", "b 桿件", "c 桿件", "d 桿件"], "answer": "C"}, {"number": 23, "prompt": "在圖示之三鉸拱結構中，A 點之水平反力為何？", "options": ["3P", "3P/2", "2P", "P"], "answer": "D"}, {"number": 24, "prompt": "下圖框架之 A 點彎矩為何？", "options": ["21PL qL2", "21PL qL4", "21PL qL4", "21PL qL6"], "answer": "A"}, {"number": 25, "prompt": "如圖所示剛構架，各構件 EI 值皆相等，基礎支承點 D 垂直下陷將使構件產生彎矩。若將其 彎矩分布繪於張力側時，最有可能為下列何者？", "options": ["", "", "", ""], "answer": "B"}, {"number": 26, "prompt": "下列何者載重分布，使懸臂梁固定端彎矩最大？", "options": ["(a)", "(b)", "(c)", "固定端彎矩值均相同"], "answer": "C"}, {"number": 27, "prompt": "如圖所示的三鉸式剛架，A、E 為鉸支承，C 為鉸接，B、D 為剛接。則有關 A 點之水平反力 Ax、垂直反力 Ay 以及 E 點之水平反力 Ex、垂直反力 Ey 之敘述，何者正確？", "options": ["Ax 0 KN，Ay 3 KN（↑）；Ex 0 KN，Ey 3 KN（↑）", "Ax 0 KN，Ay 18 KN（↑）；Ex 0 KN，Ey 18 KN（↑）", "Ax 9 KN（→），Ay 18 KN（↑）；Ex 9 KN（←），Ey 18 KN（↑）", "Ax 18 KN（→），Ay 18 KN（↑）；Ex 18 KN（←），Ey 18 KN（↑） D"], "answer": "D"}, {"number": 28, "prompt": "如圖所示之剛構架，各桿件之 EI 值皆相同，於 B 點承受一集中載重 P 作用，下列敘述何者 錯誤？", "options": ["AB 段承受較大剪力", "BC 段承受較大彎矩", "CD 段沒有承受軸力", "A 點及 D 點均承受相同的水平反力，大小為 P/2"], "answer": "B"}, {"number": 29, "prompt": "依建築物混凝土結構設計規範，進行構材斷面強度設計時，混凝土最外受壓纖維之最大應變 假設為何？", "options": ["0.004", "0.003", "0.002", "0.001"], "answer": "B"}, {"number": 30, "prompt": "關於鋼筋混凝土柱，下列敘述何者正確？", "options": ["彎矩-軸力（M-P）關係圖中，所受軸力愈大，可承受之彎矩亦愈大", "為達到「強柱弱梁」，柱彎矩強度總和必須大於梁彎矩強度總和的 1.2 倍", "柱箍筋間距最大不能超過 25 公分", "短柱應考慮二次彎矩效應"], "answer": "A"}, {"number": 31, "prompt": "有關鋼筋混凝土結構設計概念，下列敘述何者較不適當？", "options": ["強梁弱柱", "強剪弱彎", "強壓弱拉", "強節弱桿"], "answer": "B"}, {"number": 32, "prompt": "耐震設計時為了確保鋼筋混凝土結構之韌性行為，下列敘述何者錯誤？", "options": ["柱梁接頭區配置箍筋", "柱上下端同時產生塑性鉸，以使建物能變形而不倒塌", "避免桿件剪力破壞之發生早於彎矩破壞", "柱端彎矩強度總和大於梁端彎矩強度總和的 1.2 倍"], "answer": "A"}, {"number": 33, "prompt": "下圖為一偏心斜撐構架（Eccentrically Braced Frame）之示意圖，下列針對此類型鋼結構系統 之敘述，何者正確？", "options": ["地震時會先在部位(i)處產生塑鉸（plastic hinge）", "地震時主要的吸能（消能）部位在(ii)", "地震時主要的吸能（消能）部位在(iv)", "此類型設計相比於同心斜撐構架更容易出現挫屈（buckling）破壞"], "answer": "B"}, {"number": 34, "prompt": "下列何者鋼結構構材斷面彎矩強度可達塑性彎矩？①塑性設計斷面 ②細長肢材斷面 ③結 實斷面 ④半結實斷面", "options": ["①③", "②③", "②④", "①④"], "answer": "A"}, {"number": 35, "prompt": "關於銲接作業的敘述，下列何者錯誤？", "options": ["氣溫低時須先將鋼板預熱方能進行銲接作業", "戶外銲接作業主要受下雨天候影響，與風速或氣溫無關可繼續施作", "鋼板開槽銲係指鋼板在銲接前先行切割成各型倒角，以獲得較佳銲接效果", "負擔反覆荷載與衝擊荷重的銲接，以及希望發揮鋼板母材全斷面拉力強度的銲接方式，應 使用全滲透銲接"], "answer": "C"}, {"number": 36, "prompt": "由鋼骨構造所形成的特殊抗彎矩構架系統（SMRF）、同心斜撐構架系統（CBF）及偏心斜撐 構架系統（EBF）中，根據建築物耐震設計規範，其韌性容量之高低順序為何？", "options": ["SMRF＞EBF＞CBF", "EBF>＞CBF＞SMRF", "CBF＞SMRF＞EBF", "SMRF＞CBF＞EBF"], "answer": "D"}, {"number": 37, "prompt": "關於鋼筋混凝土（RC）、鋼骨（SS）、與鋼骨鋼筋混凝土（SRC）結構的比較，下列敘述何者 正確？", "options": ["三者之中韌性最好的是鋼骨鋼筋混凝土（SRC）結構", "鋼筋混凝土（RC）結構的施工複雜度高於鋼骨（SS）結構", "地震時搖晃感最強的是鋼骨（SS）結構", "在建築物樓層數與高度相等的情況下，柱子最粗的是鋼骨鋼筋混凝土（SRC）結構"], "answer": "A"}, {"number": 38, "prompt": "淺基礎之小規模建築物若位於高土壤液化潛能區，擬進行基礎加固與土壤改良，下列作法何 者錯誤？", "options": ["托底工法（under-pinning）", "微型樁（mini-pile）", "配置礫石樁", "基礎增設隔震器（isolator）"], "answer": "A"}, {"number": 39, "prompt": "下列何者不是綠建築評估之 CO2 減量指標之有效規劃策略？", "options": ["建築物底層應挑高、挑空設計，確保通風良好", "建築結構鼓勵採用木造，以達到輕量化", "柱梁鋼筋混凝土等結構構件保護層厚度，應能確保達到耐久化要求", "混凝土骨料可考慮再生骨材，以達到再生建材使用策略"], "answer": "C"}, {"number": 40, "prompt": "有關木結構與其他結構的特性比較，下列何者錯誤？", "options": ["相較木結構，鋼結構製作過程碳排放較低", "相較 RC 結構，木結構重量輕，對承載力低之地盤條件較有優勢", "相較鋼結構，木材熱傳導低，有助室內溫度穩定", "相較 RC 結構，木結構是乾式施工，現場工期較短"], "answer": "B"}], "questionCount": 40, "answerCount": 40}];